insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-illustration'), 'Final Review, Export Standards & Client Presentation', 'final-review-export-standards-and-client-presentation', '<p>Lesson <strong>6 of 6</strong> in <strong>AI Illustration</strong>: Final Review, Export Standards &amp; Client Presentation.</p><p><strong>Watch:</strong> 15:10–18:13 in the course video above (it starts at the right moment automatically). Work along in Midjourney as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of final review, export standards &amp; client presentation within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for final review, export standards &amp; client presentation in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in final review, export standards &amp; client presentation requires human judgment over automated output?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Complete Commercial Capstone Portfolio: AI Illustration</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/dds-Rblq8h8?start=910', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI LinkedIn Ghostwriting', 'ai-linkedin-ghostwriting', 'Write linkedin ghostwriting that converts — ChatGPT drafting workflows plus the human editing pass that makes it publishable.', 'Write linkedin ghostwriting that converts — ChatGPT drafting workflows plus the human editing pass that makes it publishable.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-linkedin-ghostwriting'), 'Introduction to AI Ghostwriting & Architecture', 'introduction-to-ai-ghostwriting-and-architecture', '<p>Lesson <strong>1 of 6</strong> in <strong>AI LinkedIn Ghostwriting</strong>: Introduction to AI Ghostwriting &amp; Architecture.</p><p><strong>Watch:</strong> 00:00–05:00 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores the fundamental shift from manual freelance writing to AI-augmented ghostwriting. The lesson deconstructs why single-prompt LLM generation produces generic, easily detectable LinkedIn content. It introduces the multi-agent paradigm: decoupling information gathering, draft synthesis, and voice tuning into distinct computational steps to preserve founder authenticity.</p><h3>Practical activity</h3><p>Map out a 3-agent ghostwriting workflow on paper or digital canvas (Researcher -&gt; Drafter -&gt; Critic) and identify the specific inputs required at each stage.</p><h3>Reflection check</h3><p>Why do single-prompt LinkedIn posts almost always sound like generic marketing copy, and how does multi-agent separation solve this?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Live Ghostwriting Agent Demonstration &amp; Output Inspection</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Y73BSbOt9vk', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-linkedin-ghostwriting'), 'Live Ghostwriting Agent Demonstration & Output Inspection', 'live-ghostwriting-agent-demonstration-and-output-inspection', '<p>Lesson <strong>2 of 6</strong> in <strong>AI LinkedIn Ghostwriting</strong>: Live Ghostwriting Agent Demonstration &amp; Output Inspection.</p><p><strong>Watch:</strong> 05:00–10:00 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates a functioning ghostwriting agent running live. Analyzes the differences between raw LLM output and agentic output conditioned on specific founder voice parameters. The lesson highlights key evaluation criteria: hook strength, line spacing, conversational rhythm, story-to-insight ratio, and call-to-conversation endings.</p><h3>Practical activity</h3><p>Take a sample generic AI-generated LinkedIn post and manually annotate every instance of generic phrasing, passive voice, or artificial buzzwords.</p><h3>Reflection check</h3><p>What are the three most noticeable ''AI tells'' on LinkedIn, and what specific rules can prevent them?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Building the Topic &amp; Industry Research Agent</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Y73BSbOt9vk?start=300', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-linkedin-ghostwriting'), 'Building the Topic & Industry Research Agent', 'building-the-topic-and-industry-research-agent', '<p>Lesson <strong>3 of 6</strong> in <strong>AI LinkedIn Ghostwriting</strong>: Building the Topic &amp; Industry Research Agent.</p><p><strong>Watch:</strong> 10:00–25:15 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Step-by-step build of the Research Agent. Covers scraping niche newsletters, parsing RSS feeds, extracting trending news from industry portals, and identifying content gaps. Shows how to engineer system instructions that force the agent to extract specific data points, contrarian angles, and actionable case studies rather than surface-level summaries.</p><h3>Practical activity</h3><p>Build and test the system prompt for a Research Agent targeting a specific industry (e.g., B2B SaaS or FinTech) and verify that it outputs 5 concrete story angles.</p><h3>Reflection check</h3><p>How does providing primary research data improve the Information Gain score of an AI-assisted post?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Configuring the Copywriting &amp; Tone-Feedback Agent</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Y73BSbOt9vk?start=600', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-linkedin-ghostwriting'), 'Configuring the Copywriting & Tone-Feedback Agent', 'configuring-the-copywriting-and-tone-feedback-agent', '<p>Lesson <strong>4 of 6</strong> in <strong>AI LinkedIn Ghostwriting</strong>: Configuring the Copywriting &amp; Tone-Feedback Agent.</p><p><strong>Watch:</strong> 25:15–38:30 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Focuses on the core drafting and feedback loops. Implements the Executive Voice Matrix: sentence length distribution, vocabulary constraints, preferred hook templates (e.g., ''Contrarian Take'', ''Behind-the-Scenes Breakdown'', ''Hard Truth''), and paragraph structures. Integrates a Critic Agent that scores drafts against brand guidelines before human review.</p><h3>Practical activity</h3><p>Configure a Critic Agent prompt that scores drafts from 1-10 on Voice Match, Hook Punchiness, and Jargon Absence, with mandatory rewrite suggestions.</p><h3>Reflection check</h3><p>Why is a dedicated critique step more reliable than asking the drafter agent to ''check its own work'' in a single prompt?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Creating a Slack Assistant for Instant AI Drafting &amp; Editing</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Y73BSbOt9vk?start=1515', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-linkedin-ghostwriting'), 'Creating a Slack Assistant for Instant AI Drafting & Editing', 'creating-a-slack-assistant-for-instant-ai-drafting-and-editing', '<p>Lesson <strong>5 of 6</strong> in <strong>AI LinkedIn Ghostwriting</strong>: Creating a Slack Assistant for Instant AI Drafting &amp; Editing.</p><p><strong>Watch:</strong> 38:30–45:00 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Connects the AI agent backend to Slack using webhook triggers and conversational bots. Demonstrates how a ghostwriter or founder can drop a 30-second voice note, rough bullet points, or an article link into Slack and receive three polished, tone-aligned LinkedIn drafts within seconds, complete with revision options.</p><h3>Practical activity</h3><p>Configure a webhook or test harness that accepts a raw bullet-point input and returns two formatted LinkedIn draft variations.</p><h3>Reflection check</h3><p>How does lowering the friction of capturing founder thoughts in real time increase the quality of ghostwritten content?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Advanced Workflow Optimization, Quality Control &amp; Client Delivery</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Y73BSbOt9vk?start=2310', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-linkedin-ghostwriting'), 'Advanced Workflow Optimization, Quality Control & Client Delivery', 'advanced-workflow-optimization-quality-control-and-client-delivery', '<p>Lesson <strong>6 of 6</strong> in <strong>AI LinkedIn Ghostwriting</strong>: Advanced Workflow Optimization, Quality Control &amp; Client Delivery.</p><p><strong>Watch:</strong> 45:00–61:33 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers production operations, client onboarding, batch scheduling, and continuous feedback loops. Teaches how to conduct a 45-minute monthly interview that fuels an entire month of content, how to present drafts in a client-friendly approval portal, and how to track engagement metrics to refine the agent prompts over time.</p><h3>Practical activity</h3><p>Draft a complete Client Onboarding Voice Questionnaire containing 10 deep-dive extraction questions designed to uncover personal stories and contrarian views.</p><h3>Reflection check</h3><p>What role does human editorial judgement play when AI handles 80% of the initial research and drafting workload?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Executive LinkedIn Ghostwriting Campaign &amp; System Build</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/Y73BSbOt9vk?start=2700', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Paid Ads', 'ai-paid-ads', 'Hands-on paid ads training with ChatGPT: real campaign workflows, optimization habits and a certified capstone.', 'Hands-on paid ads training with ChatGPT: real campaign workflows, optimization habits and a certified capstone.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-paid-ads'), 'Foundations of AI-Driven Paid Advertising', 'foundations-of-ai-driven-paid-advertising', '<p>Lesson <strong>1 of 6</strong> in <strong>AI Paid Ads</strong>: Foundations of AI-Driven Paid Advertising.</p><p><strong>Watch:</strong> 00:00–00:49 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the reality of modern Meta advertising: dispels common ''magic hack'' myths and establishes that winning in paid ads requires combining human strategic expertise with AI computational capabilities. The lesson outlines the core workflow: data gathering, AI-driven performance diagnostics, automated rule implementation, and high-velocity creative testing.</p><h3>Practical activity</h3><p>Define the primary advertising objective, target CPA, and minimum viable ROAS for a selected product or service offer.</p><h3>Reflection check</h3><p>Why is relying solely on AI creative generation doomed to fail without strong underlying unit economics and strategic media buying data?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Gathering Campaign &amp; Audience Data for AI Modeling</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_LYkFZmLcL4', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-paid-ads'), 'Gathering Campaign & Audience Data for AI Modeling', 'gathering-campaign-and-audience-data-for-ai-modeling', '<p>Lesson <strong>2 of 6</strong> in <strong>AI Paid Ads</strong>: Gathering Campaign &amp; Audience Data for AI Modeling.</p><p><strong>Watch:</strong> 00:49–02:05 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers extracting historical campaign data, customer reviews, competitor ad library assets, and conversion events. Teaches how to clean and structure raw advertising data into standardized CSV/text formats so that AI models can identify underlying patterns in customer objections, purchasing motivations, and creative resonance.</p><h3>Practical activity</h3><p>Export a sample set of ad performance metrics and customer reviews, and format them into a clean research context document.</p><h3>Reflection check</h3><p>What are the most critical data fields to feed into an LLM when analyzing past advertising performance?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Leveraging AI for Performance Data Analysis &amp; Audience Insights</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_LYkFZmLcL4?start=49', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-paid-ads'), 'Leveraging AI for Performance Data Analysis & Audience Insights', 'leveraging-ai-for-performance-data-analysis-and-audience-insights', '<p>Lesson <strong>3 of 6</strong> in <strong>AI Paid Ads</strong>: Leveraging AI for Performance Data Analysis &amp; Audience Insights.</p><p><strong>Watch:</strong> 02:05–04:12 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into prompting LLMs for deep advertising diagnostics. Demonstrates how to upload campaign CSVs to ChatGPT/Claude and prompt the model to identify metric anomalies, isolate winning hook themes, compute cohort retention, and segment audiences into distinct psychological profiles (pain-driven, aspiration-driven, price-conscious).</p><h3>Practical activity</h3><p>Prompt an AI model with customer review data to generate 5 distinct emotional buying angles and 10 specific objections to address in ad copy.</p><h3>Reflection check</h3><p>How does AI data analysis help uncover non-obvious customer pain points that traditional demographic targeting overlooks?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Utilizing Meta Automated Rules for Budget &amp; Bid Protection</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_LYkFZmLcL4?start=125', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-paid-ads'), 'Utilizing Meta Automated Rules for Budget & Bid Protection', 'utilizing-meta-automated-rules-for-budget-and-bid-protection', '<p>Lesson <strong>4 of 6</strong> in <strong>AI Paid Ads</strong>: Utilizing Meta Automated Rules for Budget &amp; Bid Protection.</p><p><strong>Watch:</strong> 04:12–06:10 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Detailed walkthrough of configuring automated rules inside Meta Ads Manager. Covers creating automated stop-loss triggers (pause ad if CPA exceeds 1.5x target over 3 days), automated scaling rules (increase daily budget by 20% if ROAS &gt; 3.0 with at least 10 conversions), and frequency capping alerts to prevent creative burnout.</p><h3>Practical activity</h3><p>Write out the exact logic syntax for 3 essential Meta Automated Rules: (1) Stop-Loss Kill Rule, (2) Winner Scale Rule, and (3) Fatigue Alert Rule.</p><h3>Reflection check</h3><p>Why is automating budget scaling via rules safer and more profitable than manual daily adjustments?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Exploring Meta Advantage+ &amp; AI Targeting Tools</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_LYkFZmLcL4?start=252', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-paid-ads'), 'Exploring Meta Advantage+ & AI Targeting Tools', 'exploring-meta-advantage-and-ai-targeting-tools', '<p>Lesson <strong>5 of 6</strong> in <strong>AI Paid Ads</strong>: Exploring Meta Advantage+ &amp; AI Targeting Tools.</p><p><strong>Watch:</strong> 06:10–09:15 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Analyzes Meta''s native machine learning suite: Advantage+ Shopping Campaigns (ASC), Advantage+ Audience, Advantage+ Placements, and Dynamic Product Ads. Explains how Meta''s predictive algorithms match ad creative elements to high-intent users and how media buyers should structure broad targeting to let the AI optimize delivery efficiently.</p><h3>Practical activity</h3><p>Configure the campaign settings for an Advantage+ campaign, establishing correct attribution windows (7-day click / 1-day view) and existing customer budget caps.</p><h3>Reflection check</h3><p>How does broad targeting with Advantage+ shift the media buyer''s primary job from manual audience building to creative strategy?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI-Assisted Creative Generation: Copy, Hooks, and Visuals</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_LYkFZmLcL4?start=370', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-paid-ads'), 'AI-Assisted Creative Generation: Copy, Hooks, and Visuals', 'ai-assisted-creative-generation-copy-hooks-and-visuals', '<p>Lesson <strong>6 of 6</strong> in <strong>AI Paid Ads</strong>: AI-Assisted Creative Generation: Copy, Hooks, and Visuals.</p><p><strong>Watch:</strong> 09:15–14:09 in the course video above (it starts at the right moment automatically). Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive creative production masterclass. Demonstrates how to use ChatGPT/Claude to generate 15 distinct ad copy variations across multiple formats (Short-form Punchy, Storytelling / Founder Letter, Listicle, Objection-Buster, Social Proof). Covers prompting Midjourney/DALL-E for high-CTR visual assets and dynamic product backgrounds.</p><h3>Practical activity</h3><p>Generate a full creative matrix: 3 primary text options, 3 headlines, and 3 image visual briefs for a selected e-commerce product.</p><h3>Reflection check</h3><p>What makes a high-converting ad hook on social feeds, and how can AI be directed to generate pattern-interrupting concepts?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>AI-Powered Meta Paid Advertising Campaign &amp; Testing Suite</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/_LYkFZmLcL4?start=555', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Photography & Retouching', 'ai-photography-and-retouching', 'Design client-ready photography & retouching using Photoshop — guided lessons, quality-control standards and a certified portfolio capstone.', 'Design client-ready photography & retouching using Photoshop — guided lessons, quality-control standards and a certified portfolio capstone.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-photography-and-retouching'), 'Introduction to Modern AI Retouching Workflows', 'introduction-to-modern-ai-retouching-workflows', '<p>Lesson <strong>1 of 5</strong> in <strong>AI Photography &amp; Retouching</strong>: Introduction to Modern AI Retouching Workflows.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Photoshop as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the paradigm shift in digital photography post-production. Compares traditional multi-hour manual retouching methods with modern AI-accelerated techniques. Establishes the core philosophy of professional AI retouching: AI should be used as a precision accelerator to handle repetitive pixel manipulation while human artistic direction controls final texture, realism, and aesthetic consistency.</p><h3>Practical activity</h3><p>Import three unretouched RAW portraits into your editing workspace and inspect them at 100% zoom to identify key areas requiring texture preservation versus smoothing.</p><h3>Reflection check</h3><p>Why is the preservation of authentic skin texture the single most critical standard separating professional AI retouching from amateur AI filters?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI Skin Retouching &amp; Natural Texture Smoothing</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/H6cCwOX5R_c', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-photography-and-retouching'), 'AI Skin Retouching & Natural Texture Smoothing', 'ai-skin-retouching-and-natural-texture-smoothing', '<p>Lesson <strong>2 of 5</strong> in <strong>AI Photography &amp; Retouching</strong>: AI Skin Retouching &amp; Natural Texture Smoothing.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Photoshop as you watch — pause freely and repeat steps until each one feels natural.</p><p>Step-by-step masterclass on AI skin smoothing. Demonstrates how AI neural algorithms detect facial landmarks, analyze skin tones, and smooth out blotchiness, redness, and blemishes without erasing natural skin pores. Teaches how to adjust AI smoothing intensity, mask out sensitive facial zones (eyes, lips, nostrils), and blend the AI layer with the underlying base image.</p><h3>Practical activity</h3><p>Apply AI skin smoothing to a portrait, adjust the effect intensity to 60-70%, and paint a layer mask to keep the eyes and lips completely sharp.</p><h3>Reflection check</h3><p>How does layer blending and opacity control prevent the over-processed ''plastic mannequin'' look common in automated retouching?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI-Powered Glare &amp; Reflection Removal</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/H6cCwOX5R_c', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-photography-and-retouching'), 'AI-Powered Glare & Reflection Removal', 'ai-powered-glare-and-reflection-removal', '<p>Lesson <strong>3 of 5</strong> in <strong>AI Photography &amp; Retouching</strong>: AI-Powered Glare &amp; Reflection Removal.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Photoshop as you watch — pause freely and repeat steps until each one feels natural.</p><p>Focuses on one of the hardest manual retouching challenges: removing harsh reflections and studio light glare from eyeglasses. Demonstrates how generative inpainting analyzes the visible iris and eyelid structure behind the glass to reconstruct the eye naturally while eliminating reflective flare and color fringing.</p><h3>Practical activity</h3><p>Select a portrait with eyeglass glare, use precision lasso selection around the glare artifact, and execute AI inpainting to reconstruct the eye naturally.</p><h3>Reflection check</h3><p>What visual cues must be verified after inpainting eyeglasses to ensure the subject''s gaze and eye symmetry remain anatomically correct?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Automated Garment Wrinkle Removal &amp; Fabric Cleanup</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/H6cCwOX5R_c', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-photography-and-retouching'), 'Automated Garment Wrinkle Removal & Fabric Cleanup', 'automated-garment-wrinkle-removal-and-fabric-cleanup', '<p>Lesson <strong>4 of 5</strong> in <strong>AI Photography &amp; Retouching</strong>: Automated Garment Wrinkle Removal &amp; Fabric Cleanup.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Photoshop as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers commercial wardrobe and fabric retouching. Demonstrates using generative AI to smooth deep creases, iron out distracting fabric wrinkles on shirts and suits, and remove lint/dust particles without destroying the natural weave and structure of the textile.</p><h3>Practical activity</h3><p>Select a corporate headshot with wrinkled clothing, apply AI fabric smoothing across the shoulders and chest, and verify that the garment seams remain intact.</p><h3>Reflection check</h3><p>Why is wardrobe cleanup essential in commercial and corporate headshot photography, and how does AI make it commercially viable?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Master Export, Visual QA, and Color Consistency</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/H6cCwOX5R_c', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-photography-and-retouching'), 'Master Export, Visual QA, and Color Consistency', 'master-export-visual-qa-and-color-consistency', '<p>Lesson <strong>5 of 5</strong> in <strong>AI Photography &amp; Retouching</strong>: Master Export, Visual QA, and Color Consistency.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Photoshop as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final assembly, quality assurance, and commercial delivery. Covers reviewing the full image stack at 100% and 200% magnification, checking for edge artifacts or unnatural blur halos, applying global color grading and sharpening, and exporting high-bitrate master files formatted for print (CMYK/AdobeRGB) and web (sRGB).</p><h3>Practical activity</h3><p>Perform a complete 5-point QA inspection on your finished portrait and export high-resolution master deliverables for both web and print.</p><h3>Reflection check</h3><p>What are the final quality checks required before delivering an AI-retouched image to a commercial client?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Commercial Headshot &amp; Portrait Retouching Portfolio</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/H6cCwOX5R_c', 5);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Podcast Production', 'ai-podcast-production', 'A hands-on podcast production production course built on ChatGPT: six guided lessons, real deliverables, and a certified capstone project.', 'A hands-on podcast production production course built on ChatGPT: six guided lessons, real deliverables, and a certified capstone project.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'Project Setup, Interface, and Non-Destructive Media Ingestion', 'project-setup-interface-and-non-destructive-media-ingestion', '<p>Lesson <strong>1 of 8</strong> in <strong>AI Podcast Production</strong>: Project Setup, Interface, and Non-Destructive Media Ingestion.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers setting up a Descript project, configuring desktop vs web environments, importing raw multitrack files, and understanding non-destructive timeline architecture and version history.</p><h3>Practical activity</h3><p>Create a new Descript project, import a 2-speaker audio/video recording, and verify multitrack alignment.</p><h3>Reflection check</h3><p>Why is non-destructive text editing safer for long-form media than destructive waveform editing?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI Transcription, Accuracy Settings &amp; Speaker Labeling</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'AI Transcription, Accuracy Settings & Speaker Labeling', 'ai-transcription-accuracy-settings-and-speaker-labeling', '<p>Lesson <strong>2 of 8</strong> in <strong>AI Podcast Production</strong>: AI Transcription, Accuracy Settings &amp; Speaker Labeling.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores AI speech-to-text models, custom vocabulary dictionaries, automated speaker detection, and transcript correction shortcuts.</p><h3>Practical activity</h3><p>Run AI transcription on your episode, label both speakers, and correct 5 industry-specific acronyms in the text.</p><h3>Reflection check</h3><p>How does setting custom vocabulary improve transcription accuracy for specialized industry topics?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI Text-Based Audio Editing, Cuts &amp; Highlight Creation</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'AI Text-Based Audio Editing, Cuts & Highlight Creation', 'ai-text-based-audio-editing-cuts-and-highlight-creation', '<p>Lesson <strong>3 of 8</strong> in <strong>AI Podcast Production</strong>: AI Text-Based Audio Editing, Cuts &amp; Highlight Creation.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Teaches how to edit audio by editing text. Covers deleting conversational tangents, using 1-click filler word removal, adjusting word gap durations, and extracting highlight clips.</p><h3>Practical activity</h3><p>Remove all filler words (''um'', ''uh'') across the episode and shorten silent pauses longer than 1.5 seconds.</p><h3>Reflection check</h3><p>What is the danger of over-trimming natural breath pauses in conversational speech?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Scene Architecture, Markers &amp; Project Organization</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'Scene Architecture, Markers & Project Organization', 'scene-architecture-markers-and-project-organization', '<p>Lesson <strong>4 of 8</strong> in <strong>AI Podcast Production</strong>: Scene Architecture, Markers &amp; Project Organization.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers dividing a long podcast into distinct scenes using the forward-slash (''/'') command, adding chapter markers, and organizing long-form narrative arcs.</p><h3>Practical activity</h3><p>Divide your podcast episode into at least 5 structured scenes with title markers.</p><h3>Reflection check</h3><p>How do scene markers streamline visual layout changes and video asset swapping in Descript?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Dynamic Captions, Kinetic Typography &amp; Visual Formatting</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'Dynamic Captions, Kinetic Typography & Visual Formatting', 'dynamic-captions-kinetic-typography-and-visual-formatting', '<p>Lesson <strong>5 of 8</strong> in <strong>AI Podcast Production</strong>: Dynamic Captions, Kinetic Typography &amp; Visual Formatting.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on adding dynamic animated captions, custom brand fonts, word-by-word color highlights, progress bars, and graphic overlays for video podcasts.</p><h3>Practical activity</h3><p>Create a custom kinetic caption style featuring active-word highlighting and brand color accents.</p><h3>Reflection check</h3><p>Why do dynamic word-level animated captions significantly boost viewer retention on social feeds?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Studio Sound Processing, Noise Removal &amp; Dynamics Enhancement</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'Studio Sound Processing, Noise Removal & Dynamics Enhancement', 'studio-sound-processing-noise-removal-and-dynamics-enhancement', '<p>Lesson <strong>6 of 8</strong> in <strong>AI Podcast Production</strong>: Studio Sound Processing, Noise Removal &amp; Dynamics Enhancement.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into Descript''s Studio Sound AI. Covers room echo cancellation, background noise reduction, vocal frequency restoration, and audio compression settings.</p><h3>Practical activity</h3><p>Apply Studio Sound to an imperfect audio track, fine-tune the intensity slider between 70-85%, and A/B test against the raw audio.</p><h3>Reflection check</h3><p>What are the sonic artifacts of over-applying Studio Sound (100%), and how do you achieve a natural balance?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI Speaker Training, Overdub Voice Synthesis &amp; Voice Correction</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'AI Speaker Training, Overdub Voice Synthesis & Voice Correction', 'ai-speaker-training-overdub-voice-synthesis-and-voice-correction', '<p>Lesson <strong>7 of 8</strong> in <strong>AI Podcast Production</strong>: AI Speaker Training, Overdub Voice Synthesis &amp; Voice Correction.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates training an AI voice model (Overdub) using authorized training voice samples, and using text-to-speech to replace mispronounced words directly in the transcript.</p><h3>Practical activity</h3><p>Train an authorized Overdub voice profile and correct a misspoken number or name in the episode without re-recording.</p><h3>Reflection check</h3><p>What ethical and security considerations must be enforced when cloning voices for media production?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Motion Graphics, Aspect Ratio Conversion &amp; Multitrack Cloud Export</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-podcast-production'), 'Motion Graphics, Aspect Ratio Conversion & Multitrack Cloud Export', 'motion-graphics-aspect-ratio-conversion-and-multitrack-cloud-export', '<p>Lesson <strong>8 of 8</strong> in <strong>AI Podcast Production</strong>: Motion Graphics, Aspect Ratio Conversion &amp; Multitrack Cloud Export.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final production steps: converting horizontal video (16:9) to vertical (9:16) and square (1:1), adding custom animations, and exporting WAV stems, MP4 video, and SRT captions.</p><h3>Practical activity</h3><p>Export a 9:16 vertical short-form clip with dynamic captions, along with the full mastered master audio file.</p><h3>Reflection check</h3><p>What export settings ensure maximum audio fidelity across podcast distribution platforms like Apple and Spotify?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Full AI Podcast Episode &amp; Repurposing Package</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/XW_UEGIOnjg', 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Project Management', 'ai-project-management', 'Streamline project management with Claude and Notion — practical workflows you can deploy in a real business the same week.', 'Streamline project management with Claude and Notion — practical workflows you can deploy in a real business the same week.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-project-management'), 'Next-Gen Project Management Frameworks with AI', 'next-gen-project-management-frameworks-with-ai', '<p>Lesson <strong>1 of 6</strong> in <strong>AI Project Management</strong>: Next-Gen Project Management Frameworks with AI.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and Notion as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the shift from manual administrative project tracking to AI-augmented strategic project orchestration. Explores how large language models excel at pattern recognition, complex dependency tracking, and multi-variable scheduling. Establishes the foundational principles of feeding structured project context into LLMs to generate high-fidelity management artifacts.</p><h3>Practical activity</h3><p>Draft a one-page Project Context Prompt containing business goals, team constraints, budget, and hard deadline dates.</p><h3>Reflection check</h3><p>Why does AI excel at task decomposition and risk forecasting compared to manual spreadsheet planning?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI-Driven Project Scoping, Work Breakdown &amp; SMART Goals</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Z4gighWrcMg', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-project-management'), 'AI-Driven Project Scoping, Work Breakdown & SMART Goals', 'ai-driven-project-scoping-work-breakdown-and-smart-goals', '<p>Lesson <strong>2 of 6</strong> in <strong>AI Project Management</strong>: AI-Driven Project Scoping, Work Breakdown &amp; SMART Goals.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and Notion as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates prompt engineering techniques for transforming ambiguous client briefs into hierarchical Work Breakdown Structures (WBS). Covers defining Level 1 phases, Level 2 deliverables, and Level 3 work packages with precise effort estimation, resource assignments, and SMART acceptance criteria.</p><h3>Practical activity</h3><p>Prompt Claude/ChatGPT with a raw product concept to generate a 3-level WBS containing at least 20 granular work packages.</p><h3>Reflection check</h3><p>How does enforcing SMART acceptance criteria in AI prompts prevent scope creep during sprint execution?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Generating Dynamic Gantt Charts &amp; Timelines with Claude 3</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Z4gighWrcMg', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-project-management'), 'Generating Dynamic Gantt Charts & Timelines with Claude 3', 'generating-dynamic-gantt-charts-and-timelines-with-claude-3', '<p>Lesson <strong>3 of 6</strong> in <strong>AI Project Management</strong>: Generating Dynamic Gantt Charts &amp; Timelines with Claude 3.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and Notion as you watch — pause freely and repeat steps until each one feels natural.</p><p>Teaches how to instruct AI models to output valid Mermaid.js or PlantUML code to render dynamic Gantt charts. Covers mapping task dependencies (Finish-to-Start, Start-to-Start), milestone markers, critical path highlights, and sprint cadence schedules directly in code.</p><h3>Practical activity</h3><p>Generate a Mermaid.js Gantt chart code block for a 12-week project and render it in a live Mermaid viewer to verify sequence accuracy.</p><h3>Reflection check</h3><p>What are the advantages of maintaining project schedules in text/code formats over proprietary static software files?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI Tools for Effective Stakeholder Management &amp; Communication</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Z4gighWrcMg', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-project-management'), 'AI Tools for Effective Stakeholder Management & Communication', 'ai-tools-for-effective-stakeholder-management-and-communication', '<p>Lesson <strong>4 of 6</strong> in <strong>AI Project Management</strong>: AI Tools for Effective Stakeholder Management &amp; Communication.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and Notion as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores building role-based communication pipelines. Demonstrates how to take a single weekly sprint data log and generate three customized reports: (1) Executive Summary for C-suite (ROI, milestones, blockers), (2) Technical Deep-Dive for engineering, and (3) Client Progress Update for external partners.</p><h3>Practical activity</h3><p>Create a multi-persona reporting prompt that converts a raw list of 10 completed tasks and 2 delays into 3 distinct stakeholder memos.</p><h3>Reflection check</h3><p>Why is tailored stakeholder communication essential for maintaining executive confidence during project delays?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Adaptive Agile Strategies, Risk Forecasting &amp; Resource Allocation</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Z4gighWrcMg', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-project-management'), 'Adaptive Agile Strategies, Risk Forecasting & Resource Allocation', 'adaptive-agile-strategies-risk-forecasting-and-resource-allocation', '<p>Lesson <strong>5 of 6</strong> in <strong>AI Project Management</strong>: Adaptive Agile Strategies, Risk Forecasting &amp; Resource Allocation.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and Notion as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into proactive risk management. Shows how to use AI to brainstorm non-obvious project risks, calculate Risk Priority Numbers (RPN = Probability x Impact), simulate resource bottleneck scenarios (e.g., losing a lead engineer), and generate automated mitigation trigger plans.</p><h3>Practical activity</h3><p>Build an AI-assisted Risk Assessment Matrix with 10 identified risks, mitigation strategies, and automatic escalation thresholds.</p><h3>Reflection check</h3><p>How can AI simulation models help project managers stress-test project timelines before committing to client deadlines?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>The Future of AI in Operations &amp; Continuous Project Tracking</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/Z4gighWrcMg', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-project-management'), 'The Future of AI in Operations & Continuous Project Tracking', 'the-future-of-ai-in-operations-and-continuous-project-tracking', '<p>Lesson <strong>6 of 6</strong> in <strong>AI Project Management</strong>: The Future of AI in Operations &amp; Continuous Project Tracking.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and Notion as you watch — pause freely and repeat steps until each one feels natural.</p><p>Synthesizes the complete AI project management stack. Discusses the integration of autonomous agents into Jira, Notion, and Slack to automate standup summaries, backlog grooming, velocity tracking, and sprint retrospectives.</p><h3>Practical activity</h3><p>Design an automated sprint retrospective workflow that analyzes meeting transcripts to identify process bottlenecks.</p><h3>Reflection check</h3><p>What high-level leadership and empathy skills will remain uniquely human as AI automates operational project tracking?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Enterprise Software Launch: AI Project Management Suite</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/Z4gighWrcMg', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Scriptwriting', 'ai-scriptwriting', 'A hands-on scriptwriting production course built on ChatGPT: six guided lessons, real deliverables, and a certified capstone project.', 'A hands-on scriptwriting production course built on ChatGPT: six guided lessons, real deliverables, and a certified capstone project.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'Video Ideation, Competitor Research & Topic Framing', 'video-ideation-competitor-research-and-topic-framing', '<p>Lesson <strong>1 of 8</strong> in <strong>AI Scriptwriting</strong>: Video Ideation, Competitor Research &amp; Topic Framing.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores the relationship between scriptwriting and thumbnail/title packaging. Teaches how to conduct competitor gap analysis, evaluate outlier videos, and determine optimal video length based on topic depth and audience intent.</p><h3>Practical activity</h3><p>Analyze 3 viral videos in your niche and write out their core title-thumbnail-premise packaging formula.</p><h3>Reflection check</h3><p>Why must the opening 10 seconds of a script directly validate the promise made in the title and thumbnail?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Research Frameworks &amp; Information Gathering</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'Research Frameworks & Information Gathering', 'research-frameworks-and-information-gathering', '<p>Lesson <strong>2 of 8</strong> in <strong>AI Scriptwriting</strong>: Research Frameworks &amp; Information Gathering.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers gathering proprietary data, personal case studies, expert interviews, and counter-intuitive insights. Shows how to organize raw research into a structured narrative beat sheet before writing a single word of prose.</p><h3>Practical activity</h3><p>Build a structured 6-point research dossier for a chosen video topic, isolating 3 surprising facts and 2 contrarian arguments.</p><h3>Reflection check</h3><p>How does thorough research prevent scripts from sounding like surface-level Wikipedia summaries?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>The 4 Pillars of High-Retention Video Hooks</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'The 4 Pillars of High-Retention Video Hooks', 'the-4-pillars-of-high-retention-video-hooks', '<p>Lesson <strong>3 of 8</strong> in <strong>AI Scriptwriting</strong>: The 4 Pillars of High-Retention Video Hooks.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on hook engineering. Deconstructs why 50% of viewers drop off in the first 30 seconds. Teaches the 4 Pillars of an effective hook: establishing the premise in under 5 seconds, raising emotional stakes, introducing a curiosity gap, and setting clear viewer expectations.</p><h3>Practical activity</h3><p>Write 5 distinct hook variations for the same video topic using 5 different angles (Fear of Missing Out, Bold Contrarian Claim, Story in Media Res, Extreme Experiment, Question with High Stakes).</p><h3>Reflection check</h3><p>What are the common hook mistakes that instantly cause viewers to click away?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Viewer Payoffs: Delivery, Timing &amp; Retention Architecture</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'Viewer Payoffs: Delivery, Timing & Retention Architecture', 'viewer-payoffs-delivery-timing-and-retention-architecture', '<p>Lesson <strong>4 of 8</strong> in <strong>AI Scriptwriting</strong>: Viewer Payoffs: Delivery, Timing &amp; Retention Architecture.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers the psychology of payoffs. Explains the difference between micro-payoffs (quick answers every 90 seconds) and macro-payoffs (the ultimate climax). Teaches how to deliver on promises without deflating video momentum.</p><h3>Practical activity</h3><p>Map out the timeline of a 10-minute script, placing 4 micro-payoffs and 1 macro-payoff at precise timestamp milestones.</p><h3>Reflection check</h3><p>Why does delaying all payoffs to the very end of a video result in massive mid-video audience drop-off?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Open Loop Engineering &amp; Mid-Video Engagement Pacing</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'Open Loop Engineering & Mid-Video Engagement Pacing', 'open-loop-engineering-and-mid-video-engagement-pacing', '<p>Lesson <strong>5 of 8</strong> in <strong>AI Scriptwriting</strong>: Open Loop Engineering &amp; Mid-Video Engagement Pacing.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into narrative open loops. Teaches how to plant teaser questions and unresolved story threads early in the video, maintain tension through the middle section, and weave multiple sub-plots together seamlessly.</p><h3>Practical activity</h3><p>Write an open loop sequence where a major mistake is introduced at minute 2 and resolved at minute 8.</p><h3>Reflection check</h3><p>How do open loops create an irresistible subconscious psychological drive to keep watching?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Call-to-Action (CTA) Frameworks &amp; Viewer Conversion</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'Call-to-Action (CTA) Frameworks & Viewer Conversion', 'call-to-action-cta-frameworks-and-viewer-conversion', '<p>Lesson <strong>6 of 8</strong> in <strong>AI Scriptwriting</strong>: Call-to-Action (CTA) Frameworks &amp; Viewer Conversion.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers high-conversion CTA design. Explains why abrupt ''Like and subscribe'' interruptions destroy retention. Teaches organic in-video CTAs, bridge CTAs to next videos, and value-first lead magnet integrations.</p><h3>Practical activity</h3><p>Write a 30-second seamless mid-roll CTA that transitions naturally from educational content into a product or newsletter offer.</p><h3>Reflection check</h3><p>Why are end-screen video recommendations (''watch this next'') far more effective than generic channel subscription requests?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>The POWER Editing Method: Trimming Fluff &amp; Polishing Cadence</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'The POWER Editing Method: Trimming Fluff & Polishing Cadence', 'the-power-editing-method-trimming-fluff-and-polishing-cadence', '<p>Lesson <strong>7 of 8</strong> in <strong>AI Scriptwriting</strong>: The POWER Editing Method: Trimming Fluff &amp; Polishing Cadence.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Full editing framework for written scripts. Walks through the POWER method: Pruning unnecessary filler words, Optimizing sentence brevity, Wordsmithing punchy verbs, Energizing transitions, and Rhythm-checking verbal flow by reading aloud.</p><h3>Practical activity</h3><p>Take a 1,000-word rough draft and apply the POWER method to reduce word count by 25% while increasing clarity.</p><h3>Reflection check</h3><p>Why must every script be read aloud at speaking tempo before being approved for recording?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI-Powered Scriptwriting, Brand Voice Analysis &amp; Storyboarding</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-scriptwriting'), 'AI-Powered Scriptwriting, Brand Voice Analysis & Storyboarding', 'ai-powered-scriptwriting-brand-voice-analysis-and-storyboarding', '<p>Lesson <strong>8 of 8</strong> in <strong>AI Scriptwriting</strong>: AI-Powered Scriptwriting, Brand Voice Analysis &amp; Storyboarding.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates using AI tools (Claude, ChatGPT, Subscribr) to extract creator tone from previous transcripts, generate beat sheets, brainstorm dynamic B-roll visual cues, and format multi-column production storyboards.</p><h3>Practical activity</h3><p>Feed 3 sample transcripts from a creator into an LLM to build a Brand Voice Prompt, then generate a full 1,500-word script with B-roll visual cues.</p><h3>Reflection check</h3><p>How does formatting visual B-roll cues inside the script make filming and video editing 3x faster?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>High-Retention YouTube Script &amp; Storyboard Portfolio</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/gk3r8RtTlCo', 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Social Media Management', 'ai-social-media-management', 'Build a working social media management system with ChatGPT — set it up, measure it, and scale what converts.', 'Build a working social media management system with ChatGPT — set it up, measure it, and scale what converts.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-social-media-management'), 'Modern Social Media Ecosystem & AI Opportunity', 'modern-social-media-ecosystem-and-ai-opportunity', '<p>Lesson <strong>1 of 6</strong> in <strong>AI Social Media Management</strong>: Modern Social Media Ecosystem &amp; AI Opportunity.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the modern social media landscape. Analyzes why traditional manual agency models fail due to high labor overhead and how AI tools allow a solo operator to deliver the creative output of a 5-person agency team with zero initial software costs.</p><h3>Practical activity</h3><p>Audit the social media presence of two local businesses, identifying their posting frequency, visual consistency, and engagement rates.</p><h3>Reflection check</h3><p>Why is consistency and multi-format testing the primary driver of organic social media growth?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Core Mechanics of Social Media Marketing &amp; Channel Architecture</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/utR_f5gw7tg', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-social-media-management'), 'Core Mechanics of Social Media Marketing & Channel Architecture', 'core-mechanics-of-social-media-marketing-and-channel-architecture', '<p>Lesson <strong>2 of 6</strong> in <strong>AI Social Media Management</strong>: Core Mechanics of Social Media Marketing &amp; Channel Architecture.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deconstructs the specific algorithmic mechanics of LinkedIn (professional insights, carousels), Instagram (Reels, aesthetic carousels), X (threads, contrarian thoughts), and TikTok (fast hooks, trending audio). Establishes how to build distinct content pillars for a brand.</p><h3>Practical activity</h3><p>Develop 4 distinct content pillars for a selected business niche, defining the goal and format for each pillar.</p><h3>Reflection check</h3><p>Why must the same core message be adapted into fundamentally different formats for LinkedIn vs Instagram?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>High-Value AI SMM Skills: Content Planning, Creation &amp; Analytics</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/utR_f5gw7tg', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-social-media-management'), 'High-Value AI SMM Skills: Content Planning, Creation & Analytics', 'high-value-ai-smm-skills-content-planning-creation-and-analytics', '<p>Lesson <strong>3 of 6</strong> in <strong>AI Social Media Management</strong>: High-Value AI SMM Skills: Content Planning, Creation &amp; Analytics.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into batch content generation with AI. Demonstrates prompt workflows for turning 1 core topic into 10 multi-platform posts: generating carousel text slides, punchy caption hooks, hashtag research, and community conversation starters.</p><h3>Practical activity</h3><p>Prompt an AI model to batch-generate 10 LinkedIn posts and 10 Instagram carousel scripts from a single case study.</p><h3>Reflection check</h3><p>How does batching content 30 days in advance protect the agency from creative burnout and client panic?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Client Outreach, Proposal Systems &amp; Business Prospecting</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/utR_f5gw7tg', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-social-media-management'), 'Client Outreach, Proposal Systems & Business Prospecting', 'client-outreach-proposal-systems-and-business-prospecting', '<p>Lesson <strong>4 of 6</strong> in <strong>AI Social Media Management</strong>: Client Outreach, Proposal Systems &amp; Business Prospecting.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive guide to landing social media clients with $0 ad spend. Teaches prospecting via Google Maps, Instagram DM audits, cold email frameworks, and recorded video audits that pinpoint specific flaws in a prospect''s social strategy.</p><h3>Practical activity</h3><p>Build a prospecting list of 10 qualified businesses and draft a personalized video audit outreach script.</p><h3>Reflection check</h3><p>Why is offering a specific visual audit far more effective than sending generic ''I can manage your social media'' pitch messages?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>The ''Sink or Swim'' Client Onboarding &amp; Service Delivery Protocol</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/utR_f5gw7tg', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-social-media-management'), 'The ''Sink or Swim'' Client Onboarding & Service Delivery Protocol', 'the-sink-or-swim-client-onboarding-and-service-delivery-protocol', '<p>Lesson <strong>5 of 6</strong> in <strong>AI Social Media Management</strong>: The ''Sink or Swim'' Client Onboarding &amp; Service Delivery Protocol.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Walks through the operational onboarding sprint: setting up shared Notion dashboards, collecting brand assets, defining approval protocols, establishing KPI baselines, and scheduling the first 14 days of content before public launch.</p><h3>Practical activity</h3><p>Create a Client Onboarding Notion Template containing brand asset checklists, login vaults, and approval workflows.</p><h3>Reflection check</h3><p>What are the common communication breakdowns during the first week with a new client, and how does a structured SOP prevent them?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Campaign Escalation, Reporting &amp; Long-Term Account Growth</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/utR_f5gw7tg', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-social-media-management'), 'Campaign Escalation, Reporting & Long-Term Account Growth', 'campaign-escalation-reporting-and-long-term-account-growth', '<p>Lesson <strong>6 of 6</strong> in <strong>AI Social Media Management</strong>: Campaign Escalation, Reporting &amp; Long-Term Account Growth.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers long-term agency scaling, monthly reporting, and client retention. Teaches how to use AI to generate executive monthly analytics summaries, identify winning post formats, and transition organic clients into paid ad retainers.</p><h3>Practical activity</h3><p>Draft a one-page Monthly Analytics Performance Report template highlighting top posts, follower growth, and inbound inquiries.</p><h3>Reflection check</h3><p>How does demonstrating direct business impact (inquiries, revenue) protect your agency retainer during economic downturns?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Full-Service Social Media Agency Campaign &amp; Client Pack</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/utR_f5gw7tg', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI UI/UX Design', 'ai-ui-ux-design', 'Master ui/ux design end to end with Figma: from first concept to polished, commercial deliverables you can sell.', 'Master ui/ux design end to end with Figma: from first concept to polished, commercial deliverables you can sell.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'Problem Scoping & Product Discovery with AI', 'problem-scoping-and-product-discovery-with-ai', '<p>Lesson <strong>1 of 8</strong> in <strong>AI UI/UX Design</strong>: Problem Scoping &amp; Product Discovery with AI.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the 48-hour AI product sprint methodology. Teaches how to take an ambiguous user problem, use AI prompting to articulate user pain points, define product requirements, and structure a sprint schedule.</p><h3>Practical activity</h3><p>Write a 1-page Product Problem Statement defining target users, core job-to-be-done, and measurable success criteria.</p><h3>Reflection check</h3><p>Why does rapid AI-assisted problem validation save weeks of wasted UI design effort?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI-Assisted User Research &amp; Live Interview Analysis</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'AI-Assisted User Research & Live Interview Analysis', 'ai-assisted-user-research-and-live-interview-analysis', '<p>Lesson <strong>2 of 8</strong> in <strong>AI UI/UX Design</strong>: AI-Assisted User Research &amp; Live Interview Analysis.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates conducting user research and analyzing user interview transcripts with AI. Shows how to prompt LLMs to extract pain point themes, emotional friction points, feature wishlists, and user mental models.</p><h3>Practical activity</h3><p>Feed a user interview transcript into an AI model to generate an Empathy Map and prioritized feature list.</p><h3>Reflection check</h3><p>How does AI transcription analysis prevent designer bias when synthesizing qualitative interview data?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Competitive Benchmarking, User Flows &amp; Architecture Mapping</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'Competitive Benchmarking, User Flows & Architecture Mapping', 'competitive-benchmarking-user-flows-and-architecture-mapping', '<p>Lesson <strong>3 of 8</strong> in <strong>AI UI/UX Design</strong>: Competitive Benchmarking, User Flows &amp; Architecture Mapping.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers competitor teardowns and information architecture. Uses AI to analyze competitor UX patterns (from Mobbin), identify friction points in their flows, and map out a streamlined end-to-end user flowchart.</p><h3>Practical activity</h3><p>Design a 6-step user journey flowchart mapping every screen state from onboarding to core task completion.</p><h3>Reflection check</h3><p>What are the essential screen states (empty, loading, error, success) that novice UI designers frequently forget?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Rapid Wireframing &amp; Screen Generation with Figma First Draft AI</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'Rapid Wireframing & Screen Generation with Figma First Draft AI', 'rapid-wireframing-and-screen-generation-with-figma-first-draft-ai', '<p>Lesson <strong>4 of 8</strong> in <strong>AI UI/UX Design</strong>: Rapid Wireframing &amp; Screen Generation with Figma First Draft AI.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on using Figma AI''s First Draft. Demonstrates generating full UI screen layouts from natural language prompts, adjusting component hierarchies, styling auto-layout frames, and establishing consistent typography and color design tokens.</p><h3>Practical activity</h3><p>Use Figma AI to generate 4 core application screens (Home, Detail, Form Input, User Profile), then refine styling with custom design tokens.</p><h3>Reflection check</h3><p>Why must AI-generated wireframes be manually adjusted for visual hierarchy, contrast, and spacing?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Interactive Prototyping &amp; Micro-Interaction Design with AI</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'Interactive Prototyping & Micro-Interaction Design with AI', 'interactive-prototyping-and-micro-interaction-design-with-ai', '<p>Lesson <strong>5 of 8</strong> in <strong>AI UI/UX Design</strong>: Interactive Prototyping &amp; Micro-Interaction Design with AI.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers wiring screen transitions, smart animations, interactive component variants (buttons, inputs, bottom navigation bars), and modal overlays to create a realistic, clickable prototype.</p><h3>Practical activity</h3><p>Wire all 4 app screens into an interactive prototype with smart animate transitions and clickable navigation tabs.</p><h3>Reflection check</h3><p>How do realistic micro-interactions improve the quality of user feedback during usability testing?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Automated UI Markup &amp; No-Code Component Binding</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'Automated UI Markup & No-Code Component Binding', 'automated-ui-markup-and-no-code-component-binding', '<p>Lesson <strong>6 of 8</strong> in <strong>AI UI/UX Design</strong>: Automated UI Markup &amp; No-Code Component Binding.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates using no-code plugins (Buzzy/Locofy) to automatically parse Figma auto-layout layers, tag them into functional components (forms, repeaters, action buttons), and prepare them for database binding.</p><h3>Practical activity</h3><p>Run automarkup on your Figma screens and verify that all text fields and buttons are tagged correctly as functional components.</p><h3>Reflection check</h3><p>What auto-layout naming conventions are required to make automated code generation clean and predictable?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Database Schema Generation &amp; Dynamic Data Binding</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'Database Schema Generation & Dynamic Data Binding', 'database-schema-generation-and-dynamic-data-binding', '<p>Lesson <strong>7 of 8</strong> in <strong>AI UI/UX Design</strong>: Database Schema Generation &amp; Dynamic Data Binding.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Teaches how to prompt AI to generate relational database tables matching the UI data needs, create collections, configure data types, and bind live data fields directly to the Figma layout.</p><h3>Practical activity</h3><p>Generate a database schema (Users, Tasks/Items, Categories) and bind live sample data records to your UI repeating lists.</p><h3>Reflection check</h3><p>Why is designing UI with real, variable-length database content essential for testing edge-case text overflow?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>End-to-End Usability Testing, Quality Assurance &amp; Design System Delivery</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-ui-ux-design'), 'End-to-End Usability Testing, Quality Assurance & Design System Delivery', 'end-to-end-usability-testing-quality-assurance-and-design-system-delivery', '<p>Lesson <strong>8 of 8</strong> in <strong>AI UI/UX Design</strong>: End-to-End Usability Testing, Quality Assurance &amp; Design System Delivery.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Figma as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final assembly and validation. Demonstrates testing the live functional app on mobile devices, checking responsive breakpoints, conducting accessibility contrast audits (WCAG 2.1 AA), and exporting design system assets.</p><h3>Practical activity</h3><p>Run a live prototype test on a mobile device, conduct a color contrast accessibility check, and document any UX friction points.</p><h3>Reflection check</h3><p>What are the final deliverables a product designer must hand over to ensure engineering builds the product accurately?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>48-Hour AI-Powered Mobile Product Design &amp; Functional Prototype</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/tdvlxcSep54', 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Video Editing', 'ai-video-editing', 'Produce commercial-grade video editing with CapCut — follow the full flagship tutorial, then ship a portfolio-ready capstone.', 'Produce commercial-grade video editing with CapCut — follow the full flagship tutorial, then ship a portfolio-ready capstone.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-editing'), 'Introduction to CapCut AI Video Creation Pipeline', 'introduction-to-capcut-ai-video-creation-pipeline', '<p>Lesson <strong>1 of 6</strong> in <strong>AI Video Editing</strong>: Introduction to CapCut AI Video Creation Pipeline.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CapCut as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the CapCut AI ecosystem and user interface. Overview of the generative tools available: Script to Video, AI Media generation, AI Avatars, Auto-Captions, and smart background removal. Establishes the speed and productivity benchmarks possible with AI video editing.</p><h3>Practical activity</h3><p>Open CapCut, navigate to the AI Tools panel, and familiarize yourself with the layout of the generative workspace.</p><h3>Reflection check</h3><p>How does AI video editing change the role of the editor from manual timeline cutter to creative art director?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Analyzing AI Video Formats, Visual Hooks &amp; Benchmark Examples</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/68KNzsmBarM', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-editing'), 'Analyzing AI Video Formats, Visual Hooks & Benchmark Examples', 'analyzing-ai-video-formats-visual-hooks-and-benchmark-examples', '<p>Lesson <strong>2 of 6</strong> in <strong>AI Video Editing</strong>: Analyzing AI Video Formats, Visual Hooks &amp; Benchmark Examples.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CapCut as you watch — pause freely and repeat steps until each one feels natural.</p><p>Analyzes successful commercial and viral AI-generated video formats across TikTok and YouTube Shorts. Examines why certain AI videos perform exceptionally well (fast pacing, strong audio hooks, visual variety) while poorly edited AI videos get ignored.</p><h3>Practical activity</h3><p>Deconstruct 3 viral AI-edited short-form videos, noting the time of every cut, caption style, and sound effect trigger.</p><h3>Reflection check</h3><p>What are the common visual flaws in low-effort AI videos that cause viewers to immediately swipe away?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI Media Generation: Prompts, Aspect Ratios &amp; Backgrounds</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/68KNzsmBarM', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-editing'), 'AI Media Generation: Prompts, Aspect Ratios & Backgrounds', 'ai-media-generation-prompts-aspect-ratios-and-backgrounds', '<p>Lesson <strong>3 of 6</strong> in <strong>AI Video Editing</strong>: AI Media Generation: Prompts, Aspect Ratios &amp; Backgrounds.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CapCut as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers generating original AI images and video clips directly within CapCut. Teaches how to structure text prompts for cinematic lighting, photorealistic textures, and exact 9:16 vertical composition for social feeds.</p><h3>Practical activity</h3><p>Generate 4 distinct AI background scenes inside CapCut matching a specific thematic brief (e.g., Futuristic City, Cyberpunk Lab).</p><h3>Reflection check</h3><p>Why is generating custom AI visuals superior to reusing overused, generic stock video footage?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Generating Animated Scenes &amp; AI Talking Avatars</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/68KNzsmBarM', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-editing'), 'Generating Animated Scenes & AI Talking Avatars', 'generating-animated-scenes-and-ai-talking-avatars', '<p>Lesson <strong>4 of 6</strong> in <strong>AI Video Editing</strong>: Generating Animated Scenes &amp; AI Talking Avatars.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CapCut as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into creating and directing AI talking avatars. Demonstrates selecting character models, choosing appropriate voice profiles, uploading custom voiceovers, and generating realistic lip-syncing for presenter-led videos.</p><h3>Practical activity</h3><p>Create a 30-second video featuring an AI talking avatar presenting a business tip with custom background staging.</p><h3>Reflection check</h3><p>In what commercial scenarios are AI avatars most effective (e.g., product explainers, corporate training, faceless news)?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Short-Form Video Automation from Custom Scripts &amp; Prompts</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/68KNzsmBarM', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-editing'), 'Short-Form Video Automation from Custom Scripts & Prompts', 'short-form-video-automation-from-custom-scripts-and-prompts', '<p>Lesson <strong>5 of 6</strong> in <strong>AI Video Editing</strong>: Short-Form Video Automation from Custom Scripts &amp; Prompts.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CapCut as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on the full Script-to-Video engine. Demonstrates inputting a written script, selecting AI voiceover styles, generating complete multi-clip timelines with automatic B-roll matching, and adding dynamic animated subtitles.</p><h3>Practical activity</h3><p>Input a 60-second educational script into CapCut Script-to-Video, generate the initial timeline, and customize the AI voice.</p><h3>Reflection check</h3><p>Why must the editor manually review and replace AI-selected B-roll clips to ensure tight narrative alignment?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Timeline Refinement, B-Roll Integration, Transitions &amp; Multi-Format Export</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/68KNzsmBarM', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-editing'), 'Timeline Refinement, B-Roll Integration, Transitions & Multi-Format Export', 'timeline-refinement-b-roll-integration-transitions-and-multi-format-export', '<p>Lesson <strong>6 of 6</strong> in <strong>AI Video Editing</strong>: Timeline Refinement, B-Roll Integration, Transitions &amp; Multi-Format Export.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CapCut as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final assembly and polishing. Teaches manual timeline trimming, replacing weak B-roll with high-impact clips, adding sound effects (whooshes, pops) on caption transitions, color grading, and exporting high-bitrate 1080p/4K master files.</p><h3>Practical activity</h3><p>Perform a complete final polish pass on your generated video: add 5 sound effects, adjust transition timings, and export at 1080p 60fps.</p><h3>Reflection check</h3><p>What final audio-visual quality checks are required before publishing a video to commercial social channels?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>AI Short-Form Video Campaign &amp; Faceless Channel Package</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/68KNzsmBarM', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Video Generation', 'ai-video-generation', 'A hands-on video generation production course built on Runway: six guided lessons, real deliverables, and a certified capstone project.', 'A hands-on video generation production course built on Runway: six guided lessons, real deliverables, and a certified capstone project.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Runway Gen-3 Architecture, Pricing Models & Project Setup', 'runway-gen-3-architecture-pricing-models-and-project-setup', '<p>Lesson <strong>1 of 8</strong> in <strong>AI Video Generation</strong>: Runway Gen-3 Architecture, Pricing Models &amp; Project Setup.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces Runway''s generative video infrastructure, generation credit management, user interface, and project organization. Compares Gen-3 Alpha vs Turbo models and establishes best practices for organizing narrative shot lists.</p><h3>Practical activity</h3><p>Set up a new Runway project workspace and construct a structured 6-shot cinematic shot list table.</p><h3>Reflection check</h3><p>Why is pre-planning a structured shot list essential when generating AI video with metered computational credits?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Generative Prompting, Text-to-Video &amp; Image-to-Video Foundations</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Generative Prompting, Text-to-Video & Image-to-Video Foundations', 'generative-prompting-text-to-video-and-image-to-video-foundations', '<p>Lesson <strong>2 of 8</strong> in <strong>AI Video Generation</strong>: Generative Prompting, Text-to-Video &amp; Image-to-Video Foundations.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on writing cinematic video prompts. Teaches the 5-component prompt structure: Subject, Environment, Lighting/Atmosphere, Camera Movement, and Style/Render quality. Compares pure Text-to-Video against Image-to-Video workflows.</p><h3>Practical activity</h3><p>Generate 3 video shots using Text-to-Video and 3 shots using Image-to-Video starting from a Midjourney keyframe, comparing consistency.</p><h3>Reflection check</h3><p>Why does Image-to-Video provide vastly superior control over character design and composition compared to text-only prompting?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Cinematic Camera Movements, Angles &amp; Director Controls</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Cinematic Camera Movements, Angles & Director Controls', 'cinematic-camera-movements-angles-and-director-controls', '<p>Lesson <strong>3 of 8</strong> in <strong>AI Video Generation</strong>: Cinematic Camera Movements, Angles &amp; Director Controls.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into virtual cinematography. Covers Director Mode parameters: X/Y/Z translation, Pan, Tilt, Zoom, and Roll. Teaches how to simulate complex Hollywood camera movements: tracking dolly shots, sweeping aerial drone arcs, and Dutch angles.</p><h3>Practical activity</h3><p>Create 4 variations of the same scene using 4 distinct camera moves: (1) Slow Dolly In, (2) Fast Orbit Arc, (3) Crane Tilt Down, (4) Tracking Pan.</p><h3>Reflection check</h3><p>How does intentional camera motion elevate AI footage from static motion graphics into compelling cinema?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Act-One Expressive Character Animation &amp; Motion Capture</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Act-One Expressive Character Animation & Motion Capture', 'act-one-expressive-character-animation-and-motion-capture', '<p>Lesson <strong>4 of 8</strong> in <strong>AI Video Generation</strong>: Act-One Expressive Character Animation &amp; Motion Capture.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive walkthrough of Runway Act-One. Demonstrates recording a human facial performance on webcam/phone and mapping micro-expressions, blinks, emotional shifts, and dialogue onto stylized 2D/3D AI characters with zero motion capture suits.</p><h3>Practical activity</h3><p>Record a 10-second dramatic monologue and transfer the facial performance onto an alien or historical character model using Act-One.</p><h3>Reflection check</h3><p>How does Act-One solve the notorious ''uncanny valley'' dead-eye problem of traditional AI character generation?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Prompting Templates, Scene Expansion &amp; Temporal Consistency</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Prompting Templates, Scene Expansion & Temporal Consistency', 'prompting-templates-scene-expansion-and-temporal-consistency', '<p>Lesson <strong>5 of 8</strong> in <strong>AI Video Generation</strong>: Prompting Templates, Scene Expansion &amp; Temporal Consistency.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Teaches how to extend 5-second video clips into 10-20 second continuous scenes using Extend Video. Covers maintaining temporal consistency of characters and lighting, and using prompt templates to transition between scene angles seamlessly.</p><h3>Practical activity</h3><p>Take a 5-second generation and use Runway''s Extend tool twice to produce a continuous 15-second coherent narrative shot.</p><h3>Reflection check</h3><p>What are the common distortion artifacts that occur during video extension, and how do you mitigate them with prompt constraints?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Inpainting, Object Replacement &amp; Background Removal</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Inpainting, Object Replacement & Background Removal', 'inpainting-object-replacement-and-background-removal', '<p>Lesson <strong>6 of 8</strong> in <strong>AI Video Generation</strong>: Inpainting, Object Replacement &amp; Background Removal.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers generative video inpainting and object cleanup. Demonstrates brush-selecting an unwanted object in a moving video and prompting the AI to replace or seamlessly remove it while maintaining moving shadows and reflections.</p><h3>Practical activity</h3><p>Use video inpainting to remove a modern vehicle from a historical street generation and replace it with a horse carriage.</p><h3>Reflection check</h3><p>Why is video inpainting vastly more computationally complex than static photo inpainting?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Color Grading (LUTs), Motion Tracking &amp; Depth of Field</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Color Grading (LUTs), Motion Tracking & Depth of Field', 'color-grading-luts-motion-tracking-and-depth-of-field', '<p>Lesson <strong>7 of 8</strong> in <strong>AI Video Generation</strong>: Color Grading (LUTs), Motion Tracking &amp; Depth of Field.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores post-processing within Runway and external NLEs. Covers applying cinematic Lookup Tables (LUTs) for filmic color balance, simulating optical shallow depth-of-field, motion tracking text onto 3D video planes, and frame interpolation.</p><h3>Practical activity</h3><p>Apply a film emulation LUT across 5 disparate AI shots to unify their color palette and contrast ratio.</p><h3>Reflection check</h3><p>How does unified color grading bridge the subtle aesthetic differences between separate AI generations?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Audio Integration, 3D Camera Projection &amp; Final Export</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation'), 'Audio Integration, 3D Camera Projection & Final Export', 'audio-integration-3d-camera-projection-and-final-export', '<p>Lesson <strong>8 of 8</strong> in <strong>AI Video Generation</strong>: Audio Integration, 3D Camera Projection &amp; Final Export.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Runway as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final assembly of the cinematic piece. Covers sound design synthesis (foley, ambient drones, impact hits), dialogue synchronization, 3D camera projection export, and rendering high-bitrate ProRes/H.264 master deliverables.</p><h3>Practical activity</h3><p>Assemble all generated shots into a 60-second trailer with synchronized sound effects and cinematic musical score.</p><h3>Reflection check</h3><p>What percentage of a cinematic video''s emotional impact is driven by audio and sound design?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Cinematic AI Film Trailer &amp; Director Portfolio</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/-og75MUlnFk', 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Virtual Assistant', 'ai-virtual-assistant', 'Streamline virtual assistant with ChatGPT — practical workflows you can deploy in a real business the same week.', 'Streamline virtual assistant with ChatGPT — practical workflows you can deploy in a real business the same week.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-virtual-assistant'), 'The Modern AI Virtual Assistant Role & Core Principles', 'the-modern-ai-virtual-assistant-role-and-core-principles', '<p>Lesson <strong>1 of 6</strong> in <strong>AI Virtual Assistant</strong>: The Modern AI Virtual Assistant Role &amp; Core Principles.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the evolution of the virtual assistant industry. Explores why traditional low-level VA tasks are being commoditized and how top-earning VAs position themselves as AI-powered strategic operators who solve complex problems autonomously.</p><h3>Practical activity</h3><p>Write a 1-page self-audit comparing traditional VA tasks against AI-augmented high-leverage VA deliverables.</p><h3>Reflection check</h3><p>Why does mastering AI systems allow a virtual assistant to manage 4 clients in the time previously required for 1?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Designing Repeatable Operating Systems &amp; SOPs with AI</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/fvmhQWVgaZQ', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-virtual-assistant'), 'Designing Repeatable Operating Systems & SOPs with AI', 'designing-repeatable-operating-systems-and-sops-with-ai', '<p>Lesson <strong>2 of 6</strong> in <strong>AI Virtual Assistant</strong>: Designing Repeatable Operating Systems &amp; SOPs with AI.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on system building. Demonstrates how to take messy, unorganized client instructions or 5-minute screen recordings and prompt AI to generate flawless, step-by-step Standard Operating Procedures (SOPs), decision trees, and checklists.</p><h3>Practical activity</h3><p>Convert a rough 3-minute voice recording of a client process into a polished, structured SOP with error-handling steps.</p><h3>Reflection check</h3><p>Why are clear SOPs the most valuable asset a VA can build for an executive client?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>AI-Powered Ideation, Research &amp; Task Brainstorming</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/fvmhQWVgaZQ', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-virtual-assistant'), 'AI-Powered Ideation, Research & Task Brainstorming', 'ai-powered-ideation-research-and-task-brainstorming', '<p>Lesson <strong>3 of 6</strong> in <strong>AI Virtual Assistant</strong>: AI-Powered Ideation, Research &amp; Task Brainstorming.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers high-speed executive research. Teaches prompt frameworks for competitor benchmarking, vendor comparisons, travel itinerary planning, and summarizing 50-page PDF industry reports into 1-page executive memos.</p><h3>Practical activity</h3><p>Execute a vendor comparison research prompt evaluating 3 CRM platforms for a specific business scenario.</p><h3>Reflection check</h3><p>How does structured prompt framing prevent AI research from hallucinating false business data?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Breaking Down Complex Executive Projects into Actionable Milestones</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/fvmhQWVgaZQ', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-virtual-assistant'), 'Breaking Down Complex Executive Projects into Actionable Milestones', 'breaking-down-complex-executive-projects-into-actionable-milestones', '<p>Lesson <strong>4 of 6</strong> in <strong>AI Virtual Assistant</strong>: Breaking Down Complex Executive Projects into Actionable Milestones.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Teaches project decomposition. Demonstrates taking a vague executive goal (e.g., ''Organize our annual virtual summit in 6 weeks'') and using AI to break it down into 5 phases, 25 chronological action items, deadlines, and tracking checklists.</p><h3>Practical activity</h3><p>Take a high-level executive project request and use AI to deconstruct it into a 4-week Notion project board.</p><h3>Reflection check</h3><p>Why is proactive task breakdown the hallmark of an elite executive assistant?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Continuous Skill Acquisition &amp; Tool Integration</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/fvmhQWVgaZQ', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-virtual-assistant'), 'Continuous Skill Acquisition & Tool Integration', 'continuous-skill-acquisition-and-tool-integration', '<p>Lesson <strong>5 of 6</strong> in <strong>AI Virtual Assistant</strong>: Continuous Skill Acquisition &amp; Tool Integration.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores building a personal tech stack. Covers integrating meeting transcription tools (Otter/Fathom), email triage assistants, and AI presentation builders into your daily workflow.</p><h3>Practical activity</h3><p>Configure an automated workflow where meeting transcripts are summarized into action items within 10 minutes of meeting end.</p><h3>Reflection check</h3><p>How does proactive automation of routine tasks free up time for strategic business support?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Quality Control: The ''Test &amp; Dump'' Verification Protocol</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/fvmhQWVgaZQ', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-virtual-assistant'), 'Quality Control: The ''Test & Dump'' Verification Protocol', 'quality-control-the-test-and-dump-verification-protocol', '<p>Lesson <strong>6 of 6</strong> in <strong>AI Virtual Assistant</strong>: Quality Control: The ''Test &amp; Dump'' Verification Protocol.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Details the ''Test &amp; Dump'' framework: how to systematically test new AI tools on real tasks, score them on reliability and time savings, and ruthlessly abandon tools that add friction or fail reliability tests.</p><h3>Practical activity</h3><p>Evaluate 3 new AI productivity tools using the 15-minute Test &amp; Dump rubric, documenting scores and final keep/dump decisions.</p><h3>Reflection check</h3><p>Why is avoiding tool overwhelm and sticking to proven, reliable workflows critical for professional credibility?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Executive Operating System (EOS) &amp; AI VA Operational Pack</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/fvmhQWVgaZQ', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Workflow Automation', 'ai-workflow-automation', 'A builder''s course on workflow automation: follow the full n8n workflow from zero to a working, production-ready result.', 'A builder''s course on workflow automation: follow the full n8n workflow from zero to a working, production-ready result.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Workflow Automation Fundamentals & n8n Architecture', 'workflow-automation-fundamentals-and-n8n-architecture', '<p>Lesson <strong>1 of 8</strong> in <strong>AI Workflow Automation</strong>: Workflow Automation Fundamentals &amp; n8n Architecture.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the n8n canvas, node ecosystem, and execution lifecycle. Compares traditional deterministic automation (if-this-then-that) with probabilistic agentic automation where the AI model decides the execution path dynamically based on context.</p><h3>Practical activity</h3><p>Create a new blank workflow in n8n, add a manual trigger, and test sending a simple JSON payload across two nodes.</p><h3>Reflection check</h3><p>Why is agentic workflow automation vastly more flexible than static deterministic Zapier workflows?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Building Your First AI Agent Node &amp; LLM Model Connection</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Building Your First AI Agent Node & LLM Model Connection', 'building-your-first-ai-agent-node-and-llm-model-connection', '<p>Lesson <strong>2 of 8</strong> in <strong>AI Workflow Automation</strong>: Building Your First AI Agent Node &amp; LLM Model Connection.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Step-by-step connection of the AI Agent node. Demonstrates configuring OpenAI / Anthropic chat model credentials, selecting model versions (GPT-4o / Claude 3.5 Sonnet), setting temperature parameters, and defining system instructions.</p><h3>Practical activity</h3><p>Connect an OpenAI Chat Model node to an AI Agent node in n8n and execute a basic query to verify API handshakes.</p><h3>Reflection check</h3><p>How does temperature tuning (e.g., 0.2 vs 0.7) impact deterministic reliability in business workflow automations?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Equipping Agents with System Prompts, Memory &amp; External Tools</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Equipping Agents with System Prompts, Memory & External Tools', 'equipping-agents-with-system-prompts-memory-and-external-tools', '<p>Lesson <strong>3 of 8</strong> in <strong>AI Workflow Automation</strong>: Equipping Agents with System Prompts, Memory &amp; External Tools.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into agent sub-nodes. Covers attaching Window Buffer Memory for state retention, attaching Calculator and HTTP Request tool nodes, and engineering the agent system prompt to enforce strict output schemas and tool invocation rules.</p><h3>Practical activity</h3><p>Attach a Window Buffer Memory node and a custom tool node to your AI agent, testing multi-turn conversation memory.</p><h3>Reflection check</h3><p>Why must an agent''s memory window be capped to prevent token exhaustion and unexpected API cost spikes?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Configuring Autonomous Triggers &amp; Scheduled Cron Automation</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Configuring Autonomous Triggers & Scheduled Cron Automation', 'configuring-autonomous-triggers-and-scheduled-cron-automation', '<p>Lesson <strong>4 of 8</strong> in <strong>AI Workflow Automation</strong>: Configuring Autonomous Triggers &amp; Scheduled Cron Automation.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Teaches how to automate execution without human intervention. Covers setting up Cron Triggers for scheduled morning execution, configuring Webhook Triggers for real-time external events, and managing execution error branches.</p><h3>Practical activity</h3><p>Configure a Cron Trigger node set to execute every weekday at 08:00 AM UTC and verify scheduled firing.</p><h3>Reflection check</h3><p>What are the essential error-notification safeguards required when running fully autonomous scheduled cron workflows?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Prompt Engineering for Deterministic Tool Execution &amp; Logic</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Prompt Engineering for Deterministic Tool Execution & Logic', 'prompt-engineering-for-deterministic-tool-execution-and-logic', '<p>Lesson <strong>5 of 8</strong> in <strong>AI Workflow Automation</strong>: Prompt Engineering for Deterministic Tool Execution &amp; Logic.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Focuses on prompt hardening. Demonstrates how to write system instructions that force the AI agent to follow exact execution protocols, handle missing data gracefully, format markdown tables, and avoid looping errors.</p><h3>Practical activity</h3><p>Engineer a 5-step system prompt that forces the agent to search for data, format it into Markdown, and return a strict JSON payload.</p><h3>Reflection check</h3><p>How do negative prompt constraints prevent AI agents from calling external tools in an infinite loop?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Integrating Gmail for Automated Delivery &amp; Markdown Formatting</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Integrating Gmail for Automated Delivery & Markdown Formatting', 'integrating-gmail-for-automated-delivery-and-markdown-formatting', '<p>Lesson <strong>6 of 8</strong> in <strong>AI Workflow Automation</strong>: Integrating Gmail for Automated Delivery &amp; Markdown Formatting.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Walks through integrating the Gmail node. Covers OAuth2 authentication, converting agent Markdown output into rich HTML email bodies, setting dynamic subject lines, and routing messages to specific stakeholder distribution lists.</p><h3>Practical activity</h3><p>Connect the Gmail node to your AI agent output and verify that a formatted HTML morning briefing is delivered to your inbox.</p><h3>Reflection check</h3><p>Why is converting Markdown to formatted HTML essential for executive-facing email automations?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Google Sheets Data Logging &amp; Deduplication via Knowledge Bases</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Google Sheets Data Logging & Deduplication via Knowledge Bases', 'google-sheets-data-logging-and-deduplication-via-knowledge-bases', '<p>Lesson <strong>7 of 8</strong> in <strong>AI Workflow Automation</strong>: Google Sheets Data Logging &amp; Deduplication via Knowledge Bases.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers persistent data storage and duplicate prevention. Demonstrates reading from and appending to Google Sheets, using Google Sheets as a historical log, and prompting the agent to compare incoming news/leads against the sheet to skip duplicates.</p><h3>Practical activity</h3><p>Build a Google Sheets logging step that records every processed item and checks for duplicate IDs before sending emails.</p><h3>Reflection check</h3><p>Why is historical deduplication the single most important reliability feature in automated briefing and scraping pipelines?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Production Hardening, Template Deployment &amp; Self-Hosting n8n</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-workflow-automation'), 'Production Hardening, Template Deployment & Self-Hosting n8n', 'production-hardening-template-deployment-and-self-hosting-n8n', '<p>Lesson <strong>8 of 8</strong> in <strong>AI Workflow Automation</strong>: Production Hardening, Template Deployment &amp; Self-Hosting n8n.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in n8n as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers production operations. Teaches error workflows (Error Trigger node), backing up workflows to GitHub, exporting workflow JSON templates, and setting up a self-hosted n8n instance on a Docker/VPS server for data sovereignty.</p><h3>Practical activity</h3><p>Export your complete workflow JSON, set up an Error Trigger notification branch, and document deployment steps.</p><h3>Reflection check</h3><p>What are the significant cost and data privacy advantages of self-hosting n8n compared to proprietary cloud automation tools?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Autonomous Executive Intelligence Agent &amp; Multi-Tool Workflow</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/DkV7ztrhLh8', 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI YouTube Growth Management', 'ai-youtube-growth-management', 'Build a working youtube growth management system with Claude and vidIQ — set it up, measure it, and scale what converts.', 'Build a working youtube growth management system with Claude and vidIQ — set it up, measure it, and scale what converts.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-youtube-growth-management'), 'YouTube Growth Fundamentals & Audit Methodology', 'youtube-growth-fundamentals-and-audit-methodology', '<p>Lesson <strong>1 of 5</strong> in <strong>AI YouTube Growth Management</strong>: YouTube Growth Fundamentals &amp; Audit Methodology.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and vidIQ as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the YouTube audit framework. Explains why guessing what works fails and why algorithmic diagnostics are the only reliable way to break through channel view plateaus. Outlines the 3 audit tiers: Free automated tools, expensive agency paid audits, and modern AI reasoning engines.</p><h3>Practical activity</h3><p>Define the primary growth bottleneck for a target YouTube channel (e.g., low impressions, low CTR, or poor retention).</p><h3>Reflection check</h3><p>Why is diagnosing the exact stage of viewer drop-off critical before changing video topics or production styles?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Analyzing Channel Metrics via Free YouTube Audit Tools</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/BcYqazWm3wY', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-youtube-growth-management'), 'Analyzing Channel Metrics via Free YouTube Audit Tools', 'analyzing-channel-metrics-via-free-youtube-audit-tools', '<p>Lesson <strong>2 of 5</strong> in <strong>AI YouTube Growth Management</strong>: Analyzing Channel Metrics via Free YouTube Audit Tools.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and vidIQ as you watch — pause freely and repeat steps until each one feels natural.</p><p>Evaluates free audit extensions (VidIQ, TubeBuddy, SocialBlade). Examines what free tools do well (tag inspection, SEO scorecards, basic competitor tracking) and identifies their major blind spots (lack of psychological hook analysis, retention curve context, or strategic positioning).</p><h3>Practical activity</h3><p>Run a free VidIQ/TubeBuddy audit on a target channel and document 3 actionable findings and 3 critical blind spots.</p><h3>Reflection check</h3><p>Why do generic ''SEO optimization scores'' fail to guarantee real view growth on modern YouTube?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Benchmarking Against Enterprise Paid Audit Deliverables</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/BcYqazWm3wY', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-youtube-growth-management'), 'Benchmarking Against Enterprise Paid Audit Deliverables', 'benchmarking-against-enterprise-paid-audit-deliverables', '<p>Lesson <strong>3 of 5</strong> in <strong>AI YouTube Growth Management</strong>: Benchmarking Against Enterprise Paid Audit Deliverables.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and vidIQ as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deconstructs a $500 - $1,500 agency paid YouTube audit. Analyzes human expert feedback on thumbnail design, title psychology, retention hook structure, viewer persona mapping, and monetization optimization. Identifies the high-value insights that justify paid consulting.</p><h3>Practical activity</h3><p>Compare the deliverables of an enterprise agency audit against automated tools, creating a checklist of premium audit criteria.</p><h3>Reflection check</h3><p>What qualitative human insights are typically missing from automated spreadsheet dashboards?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Leveraging ChatGPT for In-Depth Channel Diagnostics &amp; Audience Clustering</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/BcYqazWm3wY', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-youtube-growth-management'), 'Leveraging ChatGPT for In-Depth Channel Diagnostics & Audience Clustering', 'leveraging-chatgpt-for-in-depth-channel-diagnostics-and-audience-clustering', '<p>Lesson <strong>4 of 5</strong> in <strong>AI YouTube Growth Management</strong>: Leveraging ChatGPT for In-Depth Channel Diagnostics &amp; Audience Clustering.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and vidIQ as you watch — pause freely and repeat steps until each one feels natural.</p><p>Demonstrates uploading channel analytics CSVs and video titles to ChatGPT/Claude. Teaches prompt engineering for identifying outlier high-performing videos, isolating topic clusters that trigger subscriber unsubscribes, and diagnosing thumbnail CTR decay across traffic sources.</p><h3>Practical activity</h3><p>Prompt ChatGPT with 20 historical video titles and view counts to extract the 3 highest-ROI content buckets.</p><h3>Reflection check</h3><p>How does feeding raw retention data into an LLM uncover patterns in viewer fatigue that creators overlook?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Advanced Autonomous AI Auditing with ManusAI &amp; Long-Term Growth Roadmapping</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/BcYqazWm3wY', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-youtube-growth-management'), 'Advanced Autonomous AI Auditing with ManusAI & Long-Term Growth Roadmapping', 'advanced-autonomous-ai-auditing-with-manusai-and-long-term-growth-roadmapping', '<p>Lesson <strong>5 of 5</strong> in <strong>AI YouTube Growth Management</strong>: Advanced Autonomous AI Auditing with ManusAI &amp; Long-Term Growth Roadmapping.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Claude and vidIQ as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores autonomous AI research agents (ManusAI). Demonstrates automated competitor scraping, niche keyword clustering, thumbnail visual sentiment analysis, and the synthesis of a comprehensive 90-day actionable YouTube Growth Roadmap with concrete packaging recommendations.</p><h3>Practical activity</h3><p>Compile all audit findings into a 90-day strategic turnaround roadmap containing title concepts, thumbnail re-designs, and publishing schedules.</p><h3>Reflection check</h3><p>Why does combining AI computational data analysis with creator creative intuition yield the highest long-term channel ROI?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>YouTube Channel Diagnostic Audit &amp; 90-Day Growth Roadmap</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/BcYqazWm3wY', 5);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Build AI Agents', 'build-ai-agents', 'A builder''s course on ai agents: follow the full CrewAI and LangChain workflow from zero to a working, production-ready result.', 'A builder''s course on ai agents: follow the full CrewAI and LangChain workflow from zero to a working, production-ready result.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'build-ai-agents'), 'Agentic Architecture: LLMs, Tools, Planning & Memory Loops', 'agentic-architecture-llms-tools-planning-and-memory-loops', '<p>Lesson <strong>1 of 4</strong> in <strong>Build AI Agents</strong>: Agentic Architecture: LLMs, Tools, Planning &amp; Memory Loops.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CrewAI and LangChain as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the theoretical and practical foundation of autonomous AI agents. Contrasts traditional single-turn chatbots with multi-turn agentic systems. Deconstructs the 4 core components of an agent: (1) Cognitive Brain (LLM), (2) Perception/Input, (3) Tool Registry, and (4) Working Memory.</p><h3>Practical activity</h3><p>Draw an architecture diagram showing the cyclic flow between User Request -&gt; Agent Reasoning -&gt; Tool Invocation -&gt; Observation -&gt; Final Answer.</p><h3>Reflection check</h3><p>Why is tool calling capability the fundamental breakthrough that turned LLMs from passive text generators into active software agents?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Core Configuration: System Prompts, Tool Bindings &amp; API Connections</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/K4l1xc_6cyA', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'build-ai-agents'), 'Core Configuration: System Prompts, Tool Bindings & API Connections', 'core-configuration-system-prompts-tool-bindings-and-api-connections', '<p>Lesson <strong>2 of 4</strong> in <strong>Build AI Agents</strong>: Core Configuration: System Prompts, Tool Bindings &amp; API Connections.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CrewAI and LangChain as you watch — pause freely and repeat steps until each one feels natural.</p><p>Detailed walkthrough of configuring an agent runtime. Teaches how to structure system prompts that define agent capabilities, format function signatures as JSON Schema definitions, pass tool definitions to the LLM API, and parse model tool-call requests.</p><h3>Practical activity</h3><p>Write the JSON Schema definition for 2 custom tools: (1) a Web Search tool, and (2) a Mathematical Calculation tool.</p><h3>Reflection check</h3><p>Why is strict JSON Schema typing essential for preventing runtime errors during agent tool execution?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Building an End-to-End Autonomous Agent Workflow</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/K4l1xc_6cyA', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'build-ai-agents'), 'Building an End-to-End Autonomous Agent Workflow', 'building-an-end-to-end-autonomous-agent-workflow', '<p>Lesson <strong>3 of 4</strong> in <strong>Build AI Agents</strong>: Building an End-to-End Autonomous Agent Workflow.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CrewAI and LangChain as you watch — pause freely and repeat steps until each one feels natural.</p><p>Step-by-step implementation of an end-to-end working agent. Demonstrates the agent handling a complex multi-step request (e.g., researching a company, calculating financial ratios, and drafting an executive memo). Shows the execution trace, tool dispatch loop, and observation handling in real time.</p><h3>Practical activity</h3><p>Run your agent on a multi-step query that requires at least 3 sequential tool calls, logging each Thought-Action-Observation step.</p><h3>Reflection check</h3><p>How does the ReAct framework enable the model to recover when a tool call returns an error or empty result?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Agent Fine-Tuning, Error Handling &amp; Production Guardrails</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/K4l1xc_6cyA', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'build-ai-agents'), 'Agent Fine-Tuning, Error Handling & Production Guardrails', 'agent-fine-tuning-error-handling-and-production-guardrails', '<p>Lesson <strong>4 of 4</strong> in <strong>Build AI Agents</strong>: Agent Fine-Tuning, Error Handling &amp; Production Guardrails.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in CrewAI and LangChain as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers production hardening. Teaches how to prevent infinite recursion loops by setting max_iterations, implementing structured timeout handlers, designing fallback prompts, and evaluating agent accuracy across edge cases.</p><h3>Practical activity</h3><p>Inject intentional tool failures into your test suite and verify that the agent catches the error and attempts an alternative strategy.</p><h3>Reflection check</h3><p>What are the most critical safety guardrails required before deploying an autonomous AI agent in a corporate environment?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Autonomous Financial &amp; Market Research AI Agent</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/K4l1xc_6cyA', 4);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('No-Code AI Apps', 'no-code-ai-apps', 'Build and ship no-code ai apps with FlutterFlow — architecture, hands-on implementation and a deployed, certified capstone.', 'Build and ship no-code ai apps with FlutterFlow — architecture, hands-on implementation and a deployed, certified capstone.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Application Architecture & User Flow Planning', 'application-architecture-and-user-flow-planning', '<p>Lesson <strong>1 of 8</strong> in <strong>No-Code AI Apps</strong>: Application Architecture &amp; User Flow Planning.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the project vision: building a commercial AI Copywriter web application. Outlines the end-to-end architecture: User Input Form -&gt; Bubble Workflow -&gt; OpenAI API Request -&gt; JSON Response Parsing -&gt; UI Display -&gt; Database Save. Sets up the application structure.</p><h3>Practical activity</h3><p>Draw a user flow diagram mapping the exact steps from user login to input submission, API loading, and copying output to clipboard.</p><h3>Reflection check</h3><p>Why is mapping database schema and user flows prior to building UI essential in no-code app development?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Designing Responsive Front-End UI in Bubble</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Designing Responsive Front-End UI in Bubble', 'designing-responsive-front-end-ui-in-bubble', '<p>Lesson <strong>2 of 8</strong> in <strong>No-Code AI Apps</strong>: Designing Responsive Front-End UI in Bubble.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Step-by-step UI build using Bubble''s modern Flexbox layout engine. Covers building a responsive navigation bar, multi-field input forms (Product Name, Audience, Tone, Copy Type), loading spinners, and styled output cards.</p><h3>Practical activity</h3><p>Build a responsive 2-column layout in Bubble: Left column = Input Form; Right column = Generated Copy Display Area.</p><h3>Reflection check</h3><p>How does clear visual feedback (loading spinners, disabled buttons) prevent users from double-clicking during slow API calls?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>OpenAI API Fundamentals: Endpoints, Models &amp; Authentication</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'OpenAI API Fundamentals: Endpoints, Models & Authentication', 'openai-api-fundamentals-endpoints-models-and-authentication', '<p>Lesson <strong>3 of 8</strong> in <strong>No-Code AI Apps</strong>: OpenAI API Fundamentals: Endpoints, Models &amp; Authentication.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Explores the OpenAI API documentation. Covers endpoints (`/v1/chat/completions`), model selection (GPT-4o / GPT-4o-mini), authentication via Bearer tokens, token limits, and calculating per-generation API costs.</p><h3>Practical activity</h3><p>Obtain an OpenAI API secret key, configure rate limits, and calculate the estimated API cost for 1,000 copy generations.</p><h3>Reflection check</h3><p>Why is model selection (e.g., GPT-4o-mini vs GPT-4o) a critical business tradeoff between speed, quality, and profit margins?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Dynamic Prompt Engineering &amp; Parameter Tuning</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Dynamic Prompt Engineering & Parameter Tuning', 'dynamic-prompt-engineering-and-parameter-tuning', '<p>Lesson <strong>4 of 8</strong> in <strong>No-Code AI Apps</strong>: Dynamic Prompt Engineering &amp; Parameter Tuning.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into constructing dynamic API prompts. Demonstrates how to structure system messages and insert user variables (`&lt;product_name&gt;`, `&lt;target_audience&gt;`, `&lt;tone_of_voice&gt;`). Covers temperature tuning (0.7 for creativity) and presence penalties.</p><h3>Practical activity</h3><p>Write a multi-variable prompt template that takes 4 user inputs and guarantees outputting exactly 5 formatted headline options.</p><h3>Reflection check</h3><p>How does adding delimiter formatting (e.g., ''1. --- 2. ---'') make parsing multi-option AI responses trivial in no-code apps?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Configuring the Bubble API Connector &amp; Handling JSON Payloads</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Configuring the Bubble API Connector & Handling JSON Payloads', 'configuring-the-bubble-api-connector-and-handling-json-payloads', '<p>Lesson <strong>5 of 8</strong> in <strong>No-Code AI Apps</strong>: Configuring the Bubble API Connector &amp; Handling JSON Payloads.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on Bubble''s API Connector. Demonstrates adding shared headers (`Content-Type: application/json`, `Authorization: Bearer [KEY]`), creating a POST API call, entering sample parameter values, and initializing the call to establish data types in Bubble.</p><h3>Practical activity</h3><p>Configure and successfully initialize the OpenAI Chat Completion API call in Bubble''s API Connector plugin.</p><h3>Reflection check</h3><p>Why must the ''Private'' checkbox be checked on the API Key parameter in Bubble to prevent exposing credentials to the browser?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Rendering Dynamic AI Responses in Real Time</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Rendering Dynamic AI Responses in Real Time', 'rendering-dynamic-ai-responses-in-real-time', '<p>Lesson <strong>6 of 8</strong> in <strong>No-Code AI Apps</strong>: Rendering Dynamic AI Responses in Real Time.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Wired frontend workflows. Teaches how to create a button workflow that calls the API, stores the response in a Custom State, hides the loading state, and animates the output container into view with rich text formatting.</p><h3>Practical activity</h3><p>Wire the ''Generate Copy'' button workflow to call the initialized API and display the returned text in a dynamic text element.</p><h3>Reflection check</h3><p>Why is using Custom States faster and more cost-effective than writing every temporary draft immediately to the database?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Text Parsing, Data Extraction &amp; List Formatting</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Text Parsing, Data Extraction & List Formatting', 'text-parsing-data-extraction-and-list-formatting', '<p>Lesson <strong>7 of 8</strong> in <strong>No-Code AI Apps</strong>: Text Parsing, Data Extraction &amp; List Formatting.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers string manipulation and repeating groups. Demonstrates using Bubble''s `:split by` operator and regex to break a single multi-paragraph AI response into individual, selectable copy cards in a Repeating Group.</p><h3>Practical activity</h3><p>Implement a split-by formula that takes a 5-item AI response and displays each item in a distinct repeating group card with a 1-click ''Copy'' button.</p><h3>Reflection check</h3><p>How does breaking bulk text into individual modular cards elevate the perceived polish and UX of an AI application?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Relational Database Storage, User Workspaces &amp; Export Capabilities</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'no-code-ai-apps'), 'Relational Database Storage, User Workspaces & Export Capabilities', 'relational-database-storage-user-workspaces-and-export-capabilities', '<p>Lesson <strong>8 of 8</strong> in <strong>No-Code AI Apps</strong>: Relational Database Storage, User Workspaces &amp; Export Capabilities.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in FlutterFlow as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final full-stack integration. Covers creating a relational database table (`CopyItem`: Text, Tone, Prompt, Created Date, User), creating ''Save to Favorites'' workflows, building a saved projects library, and implementing 1-click clipboard copying.</p><h3>Practical activity</h3><p>Build a ''Save to Project'' database action that stores selected copy variations against the logged-in user''s account.</p><h3>Reflection check</h3><p>What are the essential database security privacy rules (Privacy Rules in Bubble) required to prevent users from seeing other users'' data?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Commercial No-Code AI Web Application &amp; Launch Suite</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/4wtzLsIib8Q', 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Prompt Engineering', 'prompt-engineering', 'A builder''s course on prompt engineering: follow the full ChatGPT workflow from zero to a working, production-ready result.', 'A builder''s course on prompt engineering: follow the full ChatGPT workflow from zero to a working, production-ready result.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering'), 'Next-Generation Context Engineering & Modern LLM Mechanics', 'next-generation-context-engineering-and-modern-llm-mechanics', '<p>Lesson <strong>1 of 6</strong> in <strong>Prompt Engineering</strong>: Next-Generation Context Engineering &amp; Modern LLM Mechanics.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deconstructs how modern transformer models operate: next-token probability distribution, attention mechanisms, and context window dynamics. Dispels the myth that AI ''thinks like a human'' and establishes why context architecture determines output quality far more than clever phrasing.</p><h3>Practical activity</h3><p>Map out the context architecture for a customer service AI, detailing system instructions, reference documents, and user state.</p><h3>Reflection check</h3><p>Why does understanding token probability prediction prevent engineers from expecting human common sense from an LLM?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Deconstructing Common Prompt Failures &amp; Hallucination Vectors</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_ZvnD73m40o', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering'), 'Deconstructing Common Prompt Failures & Hallucination Vectors', 'deconstructing-common-prompt-failures-and-hallucination-vectors', '<p>Lesson <strong>2 of 6</strong> in <strong>Prompt Engineering</strong>: Deconstructing Common Prompt Failures &amp; Hallucination Vectors.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Analyzes why 90% of people use AI incorrectly. Explores the 5 major prompt failure modes: ambiguous task framing, missing context, conflicting constraints, lack of output structure, and leading questions that trigger hallucinations.</p><h3>Practical activity</h3><p>Take 3 failed, ambiguous prompts from your past work and diagnose their specific failure mechanisms.</p><h3>Reflection check</h3><p>How does an LLM''s desire to please the user cause it to invent plausible-sounding false information when under-constrained?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>The 4 Pillars of a Production-Grade Prompt (Persona &amp; Context)</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_ZvnD73m40o', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering'), 'The 4 Pillars of a Production-Grade Prompt (Persona & Context)', 'the-4-pillars-of-a-production-grade-prompt-persona-and-context', '<p>Lesson <strong>3 of 6</strong> in <strong>Prompt Engineering</strong>: The 4 Pillars of a Production-Grade Prompt (Persona &amp; Context).</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on the PCTC Framework: (1) Defining an authoritative Persona, (2) Providing rich, unambiguous Context and source material, (3) Specifying granular Task steps, and (4) Enforcing negative Constraints (what NOT to do).</p><h3>Practical activity</h3><p>Draft a production prompt using the complete PCTC framework for an enterprise legal document analysis task.</p><h3>Reflection check</h3><p>Why are negative constraints (e.g., ''Never use passive voice; do not mention competitor names'') more effective at guiding models than positive instructions alone?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Advanced Reasoning &amp; Logic Architectures with Claude</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_ZvnD73m40o', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering'), 'Advanced Reasoning & Logic Architectures with Claude', 'advanced-reasoning-and-logic-architectures-with-claude', '<p>Lesson <strong>4 of 6</strong> in <strong>Prompt Engineering</strong>: Advanced Reasoning &amp; Logic Architectures with Claude.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into advanced cognitive prompting techniques with Claude 3.5 Sonnet. Covers Chain-of-Thought (CoT) reasoning tags (`&lt;thinking&gt;...&lt;/thinking&gt;`), Step-Back prompting, multi-perspective evaluation, and enforcing XML/JSON schema compliance.</p><h3>Practical activity</h3><p>Construct a Chain-of-Thought prompt using XML tags that forces the model to evaluate financial balance sheets before outputting a credit score recommendation.</p><h3>Reflection check</h3><p>How does forcing the model to write out its reasoning inside `&lt;thinking&gt;` tags dramatically reduce mathematical and logical errors?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Hands-on Project Build: End-to-End System Prompt Engineering</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_ZvnD73m40o', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering'), 'Hands-on Project Build: End-to-End System Prompt Engineering', 'hands-on-project-build-end-to-end-system-prompt-engineering', '<p>Lesson <strong>5 of 6</strong> in <strong>Prompt Engineering</strong>: Hands-on Project Build: End-to-End System Prompt Engineering.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Live build of a complete enterprise prompt system from scratch. Demonstrates creating few-shot demonstration blocks, dynamic variable slots, fallback handling, and schema validation for a complex multi-turn business application.</p><h3>Practical activity</h3><p>Build and test a 3-shot prompt template that converts messy customer support emails into structured JSON tickets with sentiment, priority, and category.</p><h3>Reflection check</h3><p>Why does providing 3 precise few-shot examples improve output consistency more than 5 paragraphs of descriptive rules?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Free AI Productivity Stack, Testing Harnesses &amp; Evaluation Frameworks</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/_ZvnD73m40o', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering'), 'Free AI Productivity Stack, Testing Harnesses & Evaluation Frameworks', 'free-ai-productivity-stack-testing-harnesses-and-evaluation-frameworks', '<p>Lesson <strong>6 of 6</strong> in <strong>Prompt Engineering</strong>: Free AI Productivity Stack, Testing Harnesses &amp; Evaluation Frameworks.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in ChatGPT as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers prompt evaluation and testing workflows. Teaches how to build a prompt benchmarking spreadsheet, evaluate prompt variations across 20 test inputs, score outputs on accuracy and consistency, and maintain a version-controlled prompt repository.</p><h3>Practical activity</h3><p>Set up a Prompt Benchmark Evaluation Sheet and score 2 prompt variations across 10 diverse test cases.</p><h3>Reflection check</h3><p>Why is systematic benchmarking essential before deploying prompt changes into production software?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Enterprise System Prompt Architecture &amp; Evaluation Suite</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/_ZvnD73m40o', 6);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('SaaS Boilerplate Launch', 'saas-boilerplate-launch', 'Build and ship saas boilerplate launch with Next.js and Supabase — architecture, hands-on implementation and a deployed, certified capstone.', 'Build and ship saas boilerplate launch with Next.js and Supabase — architecture, hands-on implementation and a deployed, certified capstone.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'SaaS Architecture, Tech Stack Selection & Boilerplate Setup', 'saas-architecture-tech-stack-selection-and-boilerplate-setup', '<p>Lesson <strong>1 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: SaaS Architecture, Tech Stack Selection &amp; Boilerplate Setup.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Introduces the SaaS boilerplate architecture. Deconstructs the core layers of modern SaaS: UI/Frontend framework, Authentication provider, Database/State layer, and Payment Processing. Explains why having a standardized boilerplate reduces time-to-market from 3 months to 3 days.</p><h3>Practical activity</h3><p>Diagram the architectural flow between Browser -&gt; App Server -&gt; Database -&gt; Stripe API -&gt; Stripe Webhook Handler.</p><h3>Reflection check</h3><p>Why is solving auth and billing once in a reusable boilerplate the biggest competitive advantage for solo indie developers?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Development Environment Setup &amp; Project Scaffolding</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'Development Environment Setup & Project Scaffolding', 'development-environment-setup-and-project-scaffolding', '<p>Lesson <strong>2 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: Development Environment Setup &amp; Project Scaffolding.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Covers project initialization, installing dependencies (Stripe SDK, Firebase/Supabase client, UI component libraries), configuring Tailwind CSS for styling, and setting up environment variables (`.env.local`) for development and production.</p><h3>Practical activity</h3><p>Initialize a new web project, install Stripe and backend database SDKs, and configure your `.env` configuration file.</p><h3>Reflection check</h3><p>Why must secret API keys never be exposed in client-side code or committed to public Git repositories?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>User Authentication, Session State &amp; Secure Routing</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'User Authentication, Session State & Secure Routing', 'user-authentication-session-state-and-secure-routing', '<p>Lesson <strong>3 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: User Authentication, Session State &amp; Secure Routing.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Deep dive into authentication. Implements user registration, email/password login, Google OAuth, session cookies, and server-side route guards that protect the `/dashboard` and `/account` pages from unauthenticated access.</p><h3>Practical activity</h3><p>Implement user authentication with Google login and verify that unauthenticated visitors are redirected to `/login`.</p><h3>Reflection check</h3><p>What are the security risks of checking authentication only on the client side versus server-side route hooks?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Stripe Checkout Integration &amp; Subscription Tier Management</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'Stripe Checkout Integration & Subscription Tier Management', 'stripe-checkout-integration-and-subscription-tier-management', '<p>Lesson <strong>4 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: Stripe Checkout Integration &amp; Subscription Tier Management.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Masterclass on Stripe Checkout. Demonstrates creating recurring subscription products in Stripe Dashboard, building dynamic pricing tables, creating Stripe Checkout Sessions via backend API endpoints, and redirecting users to secure checkout.</p><h3>Practical activity</h3><p>Create a monthly ($19/mo) and annual ($190/yr) subscription product in Stripe Test Mode and wire a working Checkout redirect button.</p><h3>Reflection check</h3><p>Why is using Stripe Hosted Checkout vastly more secure and easier to maintain than building custom credit card form inputs?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Secure Webhook Handlers &amp; Subscription Event Synchronization</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'Secure Webhook Handlers & Subscription Event Synchronization', 'secure-webhook-handlers-and-subscription-event-synchronization', '<p>Lesson <strong>5 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: Secure Webhook Handlers &amp; Subscription Event Synchronization.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Critical technical module on webhooks. Teaches how to set up an API endpoint (`/api/stripe-webhook`), verify webhook cryptographic signatures with `stripe.webhooks.constructEvent`, test webhooks locally with Stripe CLI, and update user subscription status in the database on `checkout.session.completed` and `customer.subscription.deleted`.</p><h3>Practical activity</h3><p>Use Stripe CLI to trigger a `checkout.session.completed` event locally and verify that your database updates the user''s `isPro` status to `true`.</p><h3>Reflection check</h3><p>Why is relying on webhooks the only reliable way to handle asynchronous subscription events like renewals, chargebacks, and cancellations?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Customer Billing Portal Configuration &amp; Account Management</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'Customer Billing Portal Configuration & Account Management', 'customer-billing-portal-configuration-and-account-management', '<p>Lesson <strong>6 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: Customer Billing Portal Configuration &amp; Account Management.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Walks through integrating the Stripe Customer Portal. Demonstrates creating a billing session endpoint that securely redirects logged-in subscribers to Stripe''s self-serve portal where they can update payment methods, download PDF tax invoices, or cancel subscriptions.</p><h3>Practical activity</h3><p>Implement a ''Manage Subscription'' button in your user settings dashboard that opens the Stripe Customer Portal.</p><h3>Reflection check</h3><p>How does providing a self-serve billing portal eliminate 80% of routine SaaS customer support requests?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Production Readiness Checklist, Security Hardening &amp; Deployment</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'saas-boilerplate-launch'), 'Production Readiness Checklist, Security Hardening & Deployment', 'production-readiness-checklist-security-hardening-and-deployment', '<p>Lesson <strong>7 of 7</strong> in <strong>SaaS Boilerplate Launch</strong>: Production Readiness Checklist, Security Hardening &amp; Deployment.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Next.js and Supabase as you watch — pause freely and repeat steps until each one feels natural.</p><p>Final production deployment. Covers switching from Stripe Test Mode to Live Mode, configuring production webhook endpoints, setting security headers, deploying the app to Vercel/Netlify, and running an end-to-end $1 test transaction.</p><h3>Practical activity</h3><p>Deploy your application to production, configure live environment variables, and verify DNS domain routing.</p><h3>Reflection check</h3><p>What are the essential post-launch health monitoring checks required on day one of a commercial SaaS launch?</p><h3>Wrapping up the lessons</h3><p>That completes the guided portion of the course. Next up: the final assessment (70% pass mark, unlimited retakes) and your capstone — <strong>Production SaaS Boilerplate Application &amp; Launch Suite</strong>. Pass both and your signed certificate is issued instantly.</p>', 'https://www.youtube-nocookie.com/embed/XUkNR-JfHwo', 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Packaging & Mockups', 'ai-packaging-and-mockups', 'Master packaging & mockups end to end with Illustrator: from first concept to polished, commercial deliverables you can sell.', 'Master packaging & mockups end to end with Illustrator: from first concept to polished, commercial deliverables you can sell.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-packaging-and-mockups'), 'Introduction & Environment Setup for AI Packaging & Mockups', 'introduction-and-environment-setup-for-ai-packaging-and-mockups', '<p>Lesson <strong>1 of 6</strong> in <strong>AI Packaging &amp; Mockups</strong>: Introduction &amp; Environment Setup for AI Packaging &amp; Mockups.</p><p><strong>Watch:</strong> 00:00–02:56 in the course video above (it starts at the right moment automatically). Work along in Illustrator as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of introduction &amp; environment setup for ai packaging &amp; mockups within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for introduction &amp; environment setup for ai packaging &amp; mockups in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in introduction &amp; environment setup for ai packaging &amp; mockups requires human judgment over automated output?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Core Frameworks, Prompting &amp; Tool Workflows</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XNuywdUDc6c', 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-packaging-and-mockups'), 'Core Frameworks, Prompting & Tool Workflows', 'core-frameworks-prompting-and-tool-workflows', '<p>Lesson <strong>2 of 6</strong> in <strong>AI Packaging &amp; Mockups</strong>: Core Frameworks, Prompting &amp; Tool Workflows.</p><p><strong>Watch:</strong> 02:56–05:52 in the course video above (it starts at the right moment automatically). Work along in Illustrator as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of core frameworks, prompting &amp; tool workflows within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for core frameworks, prompting &amp; tool workflows in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in core frameworks, prompting &amp; tool workflows requires human judgment over automated output?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Applied Production &amp; Hands-on Implementation</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XNuywdUDc6c?start=176', 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-packaging-and-mockups'), 'Applied Production & Hands-on Implementation', 'applied-production-and-hands-on-implementation', '<p>Lesson <strong>3 of 6</strong> in <strong>AI Packaging &amp; Mockups</strong>: Applied Production &amp; Hands-on Implementation.</p><p><strong>Watch:</strong> 05:52–08:48 in the course video above (it starts at the right moment automatically). Work along in Illustrator as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of applied production &amp; hands-on implementation within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for applied production &amp; hands-on implementation in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in applied production &amp; hands-on implementation requires human judgment over automated output?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Refinement, Quality Control &amp; Edge-Case Handling</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XNuywdUDc6c?start=352', 3);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-packaging-and-mockups'), 'Refinement, Quality Control & Edge-Case Handling', 'refinement-quality-control-and-edge-case-handling', '<p>Lesson <strong>4 of 6</strong> in <strong>AI Packaging &amp; Mockups</strong>: Refinement, Quality Control &amp; Edge-Case Handling.</p><p><strong>Watch:</strong> 08:48–11:44 in the course video above (it starts at the right moment automatically). Work along in Illustrator as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of refinement, quality control &amp; edge-case handling within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for refinement, quality control &amp; edge-case handling in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in refinement, quality control &amp; edge-case handling requires human judgment over automated output?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Advanced Optimization &amp; Multi-Channel Integration</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XNuywdUDc6c?start=528', 4);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-packaging-and-mockups'), 'Advanced Optimization & Multi-Channel Integration', 'advanced-optimization-and-multi-channel-integration', '<p>Lesson <strong>5 of 6</strong> in <strong>AI Packaging &amp; Mockups</strong>: Advanced Optimization &amp; Multi-Channel Integration.</p><p><strong>Watch:</strong> 11:44–14:40 in the course video above (it starts at the right moment automatically). Work along in Illustrator as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of advanced optimization &amp; multi-channel integration within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for advanced optimization &amp; multi-channel integration in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in advanced optimization &amp; multi-channel integration requires human judgment over automated output?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Final Review, Export Standards &amp; Client Presentation</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/XNuywdUDc6c?start=704', 5);
