insert into public.testimonials (name, role, quote, course_id) values ('Adaeze Okonkwo', 'Freelance Copywriter, Lagos', 'I finished AI Copywriting on a Saturday and closed my first retainer client the following week. The editing pass that removes the robotic tone was worth the fee on its own — my drafts finally sound like me, just faster.', (select id from public.courses where slug = 'ai-copywriting'));
insert into public.testimonials (name, role, quote, course_id) values ('Ibrahim Musa', 'Operations Manager, Kano', 'The workflow automation course paid for itself in the first month. We automated our order confirmations and lead follow-ups in n8n, and I didn''t write a single line of code. My capstone project is now running live in our business.', (select id from public.courses where slug = 'ai-workflow-automation'));
insert into public.testimonials (name, role, quote, course_id) values ('Funmilayo Adeyemi', 'Content Creator, Ibadan', 'AI YouTube Growth gave me an actual production system, not motivation fluff. Three months after my capstone, my channel crossed 8,000 subscribers and I run everything in about six hours a week.', (select id from public.courses where slug = 'ai-youtube-growth-management'));
insert into public.testimonials (name, role, quote, course_id) values ('Chidi Nwankwo', 'Data Analyst, Abuja', 'AI Data Entry & Analysis is how analysis should be taught. The ChatGPT pair-working approach meant I was never stuck for more than a minute, and the certificate verification link went straight on my CV.', (select id from public.courses where slug = 'ai-data-entry-and-analysis'));
insert into public.testimonials (name, role, quote, course_id) values ('Amina Bello', 'Customer Success Lead, Port Harcourt', 'We deployed the support chatbot from my capstone project and our ticket volume dropped by half. My manager asked where I learned it — I just sent her the certificate verification link.', (select id from public.courses where slug = 'ai-customer-support'));
insert into public.testimonials (name, role, quote, course_id) values ('Tunde Bakare', 'Founder, Lagos', 'I built and launched my first no-code AI app in under two weeks. As a non-technical founder, shipping something real — auth, database and all — felt impossible before this course.', (select id from public.courses where slug = 'no-code-ai-apps'));
insert into public.testimonials (name, role, quote, course_id) values ('Ngozi Eze', 'Digital Marketer, Enugu', 'The AI Paid Ads course is clearly taught from real campaigns. The creative testing system cut our cost per lead by 40%, and the AI creative pipeline means we never run out of fresh angles.', (select id from public.courses where slug = 'ai-paid-ads'));
insert into public.testimonials (name, role, quote, course_id) values ('Suleiman Abdullahi', 'Voiceover Artist, Kaduna', 'I was afraid AI would replace my voice work. The voice cloning course showed me how to scale it instead — I now deliver projects in three languages and my turnaround went from days to hours.', (select id from public.courses where slug = 'ai-voice-cloning-and-dubbing'));
